            body_children.append(
                <div class="shopping-footer">
                    <span class="total">Total: ${total_text}</span>
                    <button class="btn-clear" onClick={clear_list}>Clear</button>
                </div>
            );
        }

        return
            <div class="column">
                <h2>Meal Shopping List</h2>
                <div class="input-row">
                    <input
                        class="input"
                        value={meal_text}
                        onChange={lambda (e: ChangeEvent) { meal_text = e.target.value; }}
                        onKeyPress={lambda (e: KeyboardEvent) { if e.key == "Enter" {
                            generate_meal_list();
                        }}}
                        placeholder="Describe a meal, e.g. 'chicken stir fry for 4'"
                    />
                    <button
                        class="btn-generate"
                        onClick={generate_meal_list}
                        disabled={generating}
                    >
                        {generate_label}
                    </button>
                </div>
                {body_children}
            </div>;
    }

    def:pub app -> JsxElement {
        return
            <div class="container">
                <h1>AI Day Planner</h1>
                <div class="two-column">
                    <TasksColumn/>
                    <ShoppingColumn/>
                </div>
            </div>;
    }
}

