"""AI Day Planner -- graph flattened into a dict-of-lists adjacency store."""

cl {
    import from frontend { app as ClientApp }

    def:pub app -> JsxElement {
        return <ClientApp/>;
    }
}

sv {
    enum Category { WORK, PERSONAL, SHOPPING, HEALTH, FITNESS, OTHER }

    enum Unit { PIECE, LB, OZ, CUP, TBSP, TSP, BUNCH }

    obj Ingredient {
        has name: str,
            quantity: float,
            unit: Unit,
            cost: float,
            carby: bool;
    }

    sem Ingredient.cost = "Estimated cost in USD";
    sem Ingredient.carby = "True if this ingredient is high in carbohydrates";

    def categorize(title: str) -> Category by llm();
    sem categorize = "Categorize a task based on its title";

    def generate_shopping_list(meal_description: str) -> list[Ingredient] by llm();
    sem generate_shopping_list = "Generate a shopping list of ingredients needed for a described meal";

    # The root graph is represented as an adjacency map: kind -> child records.
    glob store: dict[str, list[dict]] = {"tasks": [], "shopping": []};
    glob id_counter: int = 0;

    def next_id -> str {
        global id_counter;
        id_counter = id_counter + 1;
        return "n" + str(id_counter);
    }

    def traverse_children(kind: str) -> list[dict] {
        found: list[dict] = [];
        children = store[kind];
        i = 0;
        while i < len(children) {
            found.append(children[i]);
            i = i + 1;
        }
        return found;
    }

    def find_child(kind: str, node_id: str) -> int {
        children = store[kind];
        i = 0;
        while i < len(children) {
            if children[i]["id"] == node_id {
                return i;
            }
            i = i + 1;
        }
        return -1;
    }

    def:priv create_task(title: str) -> dict {
        category = str(categorize(title)).split(".")[-1].lower();
        record = {
            "id": next_id(),
            "title": title,
            "done": False,
            "category": category
        };
        store["tasks"].append(record);
        return record;
    }

    def:priv fetch_tasks -> list[dict] {
        return traverse_children("tasks");
    }

    def:priv flip_task_done(task_id: str) -> dict {
        idx = find_child("tasks", task_id);
        if idx < 0 {
            return {};
        }
        record = store["tasks"][idx];
        record["done"] = not record["done"];
        return record;
    }

    def:priv remove_task(task_id: str) -> dict {
        idx = find_child("tasks", task_id);
        if idx >= 0 {
            store["tasks"].pop(idx);
        }
        return {"deleted": task_id};
    }

    def:priv build_shopping(meal_description: str) -> list[dict] {
        store["shopping"] = [];
        ingredients = generate_shopping_list(meal_description);
        i = 0;
        while i < len(ingredients) {
            ing = ingredients[i];
            record = {
                "id": next_id(),
                "name": ing.name,
                "quantity": ing.quantity,
                "unit": str(ing.unit).split(".")[-1].lower(),
                "cost": ing.cost,
                "carby": ing.carby
            };
            store["shopping"].append(record);
            i = i + 1;
        }
        return traverse_children("shopping");
    }

    def:priv fetch_shopping -> list[dict] {
        return traverse_children("shopping");
    }

    def:priv wipe_shopping -> dict {
        store["shopping"] = [];
        return {"cleared": True};
    }
}

