"""Little X - Social graph backend, flat dict/list implementation.

All data lives in module-level dict tables keyed by string ids. Relationships
are dict-of-lists adjacency maps (follower id -> followed ids, profile id ->
tweet ids, ...). Every operation is a plain function that walks the maps with
loops; the current caller is tracked in a module-level session dict.
"""

import datetime;

def _now -> str {
    return datetime.datetime.now(datetime.UTC).replace(tzinfo=None).isoformat() + "Z";
}

