def next_id(prefix: str) -> str {
    id_counter["n"] = id_counter["n"] + 1;
    return prefix + str(id_counter["n"]);
}

def adj_list(table: dict, key: str) -> list[str] {
    if key in table {
        return table[key];
    }
    return [];
}

def adj_add(table: dict, key: str, val: str) -> None {
    lst: list = [];
    if key in table {
        lst = table[key];
    }
    lst.append(val);
    table[key] = lst;
}

def adj_remove_first(table: dict, key: str, val: str) -> None {
    if key not in table {
        return;
    }
    lst = table[key];
    i = 0;
    removed = False;
    out: list = [];
    while i < len(lst) {
        if lst[i] == val and removed == False {
            removed = True;
        } else {
            out.append(lst[i]);
        }
        i = i + 1;
    }
    table[key] = out;
}

def my_profile_id -> str {
