glob tweets: dict[str, dict] = {};
glob feed_order: list[str] = [];
glob comments: dict[str, dict] = {};
glob comment_edges: dict[str, list[str]] = {};
glob counter: dict[str, int] = {"n": 0};

def now_stamp -> str {
    return datetime.datetime.now().strftime("%H:%M");
}

def next_id(prefix: str) -> str {
    counter["n"] = counter["n"] + 1;
    return prefix + str(counter["n"]);
}

def load_feed -> list[dict] {
    rows: list = [];
    i = 0;
    while i < len(feed_order) {
        rows.append(tweets[feed_order[i]]);
        i = i + 1;
    }
    return rows;
}

def seed_feed -> list[dict] {
    if len(feed_order) == 0 {
        i = 0;
        while i < len(SEED_TWEETS) {
            s = SEED_TWEETS[i];
            create_tweet(s["content"], s["author"]);
            i = i + 1;
        }
    }
    return load_feed();
}

def create_tweet(content: str, author: str) -> dict {
    tid = next_id("t");
    row = {
        "_jac_id": tid,
        "content": content,
        "author": author,
        "likes": 0,
        "retweets": 0,
        "comments": 0,
        "created_at": now_stamp()
    };
    tweets[tid] = row;
    feed_order.append(tid);
    return row;
}

def like_tweet(tid: str) -> dict {
    tweets[tid]["likes"] = tweets[tid]["likes"] + 1;
    return tweets[tid];
}

def unlike_tweet(tid: str) -> dict {
    if tweets[tid]["likes"] > 0 {
        tweets[tid]["likes"] = tweets[tid]["likes"] - 1;
    }
    return tweets[tid];
}

def retweet_tweet(tid: str) -> dict {
    tweets[tid]["retweets"] = tweets[tid]["retweets"] + 1;
    return tweets[tid];
}

def unretweet_tweet(tid: str) -> dict {
    if tweets[tid]["retweets"] > 0 {
        tweets[tid]["retweets"] = tweets[tid]["retweets"] - 1;
    }
    return tweets[tid];
}

def add_comment(tid: str, content: str, author: str) -> dict {
    cid = next_id("c");
    comments[cid] = {
        "_jac_id": cid,
        "content": content,
        "author": author,
        "created_at": now_stamp()
    };
    lst: list = [];
    if tid in comment_edges {
        lst = comment_edges[tid];
    }
    lst.append(cid);
    comment_edges[tid] = lst;
    tweets[tid]["comments"] = tweets[tid]["comments"] + 1;
    return tweets[tid];
}

def load_comments(tid: str) -> list[dict] {
    rows: list = [];
    ids: list = [];
    if tid in comment_edges {
        ids = comment_edges[tid];
    }
    i = 0;
    while i < len(ids) {
        rows.append(comments[ids[i]]);
        i = i + 1;
    }
    return rows;
}

glob app_state: dict = {
    "screen": "splash",
    "authMode": "login",
    "authUser": "",
    "authPass": "",
    "authPass2": "",
    "authError": "",
    "me": "",
    "tab": "home",
    "profileUser": "",
    "tweets": [],
    "liked": [],
    "retweeted": [],
    "draft": "",
    "query": "",
    "commentTid": "",
    "commentList": [],
    "commentDraft": ""
};

def avatar_for(seed: str) -> str {
    return "https://api.dicebear.com/7.x/thumbs/png?seed=" + seed;
}

def newest_first(xs: list) -> list {
    r: list = [];
    i = 0;
    while i < len(xs) {
        r = [xs[i]] + r;
        i = i + 1;
    }
    return r;
}

def boot_app -> None {
    app_state["tweets"] = seed_feed();
    if app_state["screen"] == "splash" {
        app_state["screen"] = "auth";
    }
}

def reload -> None {
    app_state["tweets"] = load_feed();
}

def submit_auth -> None {
    app_state["authError"] = "";
    trimmed_user = app_state["authUser"].strip();
    if len(trimmed_user) < 3 {
        app_state["authError"] = "Username must be at least 3 characters.";
        return;
    }
    if len(app_state["authPass"]) < 6 {
        app_state["authError"] = "Password must be at least 6 characters.";
        return;
    }
    if app_state["authMode"] == "signup" {
        if app_state["authPass"] != app_state["authPass2"] {
            app_state["authError"] = "Passwords do not match.";
            return;
        }
    }
    app_state["me"] = trimmed_user;
    app_state["authPass"] = "";
    app_state["authPass2"] = "";
    app_state["tab"] = "home";
    app_state["screen"] = "app";
}

def logout -> None {
    app_state["me"] = "";
    app_state["authUser"] = "";
    app_state["screen"] = "auth";
    app_state["authMode"] = "login";
}

def post -> None {
    txt = app_state["draft"].strip();
    if not txt {
        return;
    }
    create_tweet(txt, app_state["me"]);
    app_state["draft"] = "";
    reload();
}

def id_in_list(tid: str, ids: list) -> bool {
    i = 0;
    while i < len(ids) {
        if ids[i] == tid {
            return True;
        }
        i = i + 1;
    }
    return False;
}

def remove_id(tid: str, ids: list) -> list {
    kept: list = [];
    i = 0;
    while i < len(ids) {
        if ids[i] != tid {
            kept.append(ids[i]);
        }
        i = i + 1;
    }
    return kept;
}

def like_tweet_ui(tid: str) -> None {
    if id_in_list(tid, app_state["liked"]) {
        unlike_tweet(tid);
        app_state["liked"] = remove_id(tid, app_state["liked"]);
    } else {
        like_tweet(tid);
        app_state["liked"] = app_state["liked"] + [tid];
    }
    reload();
}

def retweet_tweet_ui(tid: str) -> None {
    if id_in_list(tid, app_state["retweeted"]) {
        unretweet_tweet(tid);
        app_state["retweeted"] = remove_id(tid, app_state["retweeted"]);
    } else {
        retweet_tweet(tid);
        app_state["retweeted"] = app_state["retweeted"] + [tid];
    }
    reload();
}

def open_comments(tid: str) -> None {
    app_state["commentTid"] = tid;
    app_state["commentDraft"] = "";
    app_state["commentList"] = load_comments(tid);
}

def close_comments -> None {
    app_state["commentTid"] = "";
    app_state["commentList"] = [];
    app_state["commentDraft"] = "";
}

def submit_comment -> None {
    txt = app_state["commentDraft"].strip();
    if not txt {
        return;
    }
    if app_state["commentTid"] == "" {
        return;
    }
    add_comment(app_state["commentTid"], txt, app_state["me"]);
    app_state["commentDraft"] = "";
    app_state["commentList"] = load_comments(app_state["commentTid"]);
    reload();
}

def open_profile(u: str) -> None {
    app_state["profileUser"] = u;
    app_state["tab"] = "profile";
}

def render_tweet_card(t: dict) -> str {
    line = "@" + t["author"] + " · " + t["created_at"] + "\n";
    line = line + "  " + t["content"] + "\n";
    like_mark = " ";
    if id_in_list(t["_jac_id"], app_state["liked"]) {
        like_mark = "*";
    }
    rt_mark = " ";
    if id_in_list(t["_jac_id"], app_state["retweeted"]) {
        rt_mark = "*";
    }
    line = line + "  hearts:" + str(t["likes"]) + like_mark;
    line = line + " comments:" + str(t["comments"]);
    line = line + " repeats:" + str(t["retweets"]) + rt_mark;
    return line;
}

def render_feed -> str {
    ordered = newest_first(app_state["tweets"]);
    parts: list = [];
    i = 0;
    while i < len(ordered) {
        parts.append(render_tweet_card(ordered[i]));
        i = i + 1;
    }
    out = "";
    j = 0;
    while j < len(parts) {
        out = out + parts[j];
        if j < len(parts) - 1 {
            out = out + "\n";
        }
        j = j + 1;
    }
    return out;
}

with entry {
