    nid = id_state["next"];
    id_state["next"] = nid + 1;
    return f"user_{nid}";
}

# List all users
def list_users() -> list[dict] {
    result: list[dict] = [];
    for user_id in users.keys() {
        u = users[user_id];
        result.append({"id": user_id, "name": u["name"], "email": u["email"]});
    }
    return result;
}

# Get single user
def get_user(user_id: str) -> dict {
    if user_id in users {
        u = users[user_id];
        return {
            "id": user_id,
            "name": u["name"],
            "email": u["email"],
            "created_at": u["created_at"]
        };
    }
    return {"error": "Not found"};
}

# Create user
def create_user(name: str, email: str) -> dict {
    user_id = new_user_id();
    users[user_id] = {
        "name": name,
        "email": email,
        "created_at": datetime.now().isoformat()
    };
    return {"id": user_id, "name": name, "email": email};
}

# Update user
def update_user(user_id: str, name: str = "", email: str = "") -> dict {
    if user_id in users {
        u = users[user_id];
        if name {
            u["name"] = name;
        }
        if email {
            u["email"] = email;
        }
        return {"id": user_id, "name": u["name"], "email": u["email"]};
    }
    return {"error": "Not found"};
}

# Delete user
def delete_user(user_id: str) -> dict {
    if user_id in users {
        users.pop(user_id);
        return {"deleted": True};
    }
    return {"error": "Not found"};
}

# Health check
def health() -> dict {
    return {"status": "ok", "timestamp": datetime.now().isoformat()};
}

