"""Phase inspector: the full definition of whichever phase is selected,
plus that phase's captured context.

Pick a phase id and this shows that state's role prompt (its `sem` string --
the same text the router shows the model), its short blurb, the tools it
exposes, and the contents of its context: the messages that phase last worked
with (system prompt, the kickoff directive, and the tool turns it
accumulated). Phases live in a plain dict keyed by id; per-phase context lives
in a second dict of {"found": bool, "messages": [...]} records, populated per
lookup. Every field read is guarded against a missing selection or a phase
that has not run yet.
"""

glob phases: dict[str, dict] = {};
glob phase_contexts: dict[str, dict] = {};

def add_phase(
    id: str, label: str, desc: str, role_prompt: str, tools: list[str]
) -> None {
    phases[id] = {
        "id": id, "label": label, "desc": desc, "sem": role_prompt,
        "tools": tools
    };
}

def capture_context(id: str, messages: list[dict]) -> None {
    phase_contexts[id] = {"found": True, "messages": messages};
}

def fetch_context(id: str) -> dict {
    return phase_contexts.get(id, {"found": False, "messages": []});
}

def inspect_phase(selected: str) -> list[str] {
    sel: dict = {};
    for (pid, p) in phases.items() {
        if pid == selected {
            sel = p;
        }
    }
    lines: list[str] = [];
    if len(sel) == 0 {
        lines.append("phase");
        lines.append("  Pick a phase id to inspect it.");
        return lines;
    }
    lines.append("phase " + sel["label"]);
    lines.append("  " + sel["desc"]);
    lines.append("  role:");
    role_prompt = sel["sem"];
    if role_prompt == "" {
        lines.append("    (no role prompt)");
    } else {
        lines.append("    " + role_prompt);
    }
    if len(sel["tools"]) > 0 {
        lines.append("  tools:");
        for t in sel["tools"] {
            lines.append("    - " + t);
        }
    }
    context = fetch_context(selected);
    has_ctx = context["found"] and len(context["messages"]) > 0;
    if not has_ctx {
        lines.append("  context:");
        lines.append(
            "    No captured context yet - run a turn, then inspect this phase."
        );
        return lines;
    }
    lines.append(f"  context: {len(context['messages'])} msg");
    i = 0;
    while i < len(context["messages"]) {
        m = context["messages"][i];
        role = m.get("role", "?");
        lines.append(f"    [{i}] {role}");
        content = m.get("content", "");
        if content != "" {
            lines.append("        " + content);
        }
        tool_calls = m.get("tools", []);
        if len(tool_calls) > 0 {
            lines.append("        tools: " + ", ".join(tool_calls));
        }
        i = i + 1;
    }
    return lines;
}

