"""The `code` command: index-backed code intelligence for agents.

Where `grep` answers "which lines contain this string", `code` answers
"where is this symbol defined, everywhere it is used, what type it has, and
which traversal routines touch it" -- the structural questions a text search
cannot. It is grep's structural successor: a thin, JSON-by-default shim over
a set of plain dict indexes built for terminal-driven AI agents.

Output is machine-readable JSON by default (every payload carries a
`schema_version` so consumers can pin a shape); pass text=True for the
human-readable rendering. Exit codes are stable: 0 = ok, 1 = usage/runtime
error, 2 = nothing found for the query.
"""

import json;

glob SCHEMA_VERSION: int = 1;

# name -> {"kind": str, "file": str, "line": int, "type": str}
glob symbols: dict[str, dict] = {};
# name -> list of {"file": str, "line": int, "mode": "read"|"write"}
glob uses_index: dict[str, list[dict]] = {};
# node-type name -> list of traversal routine names that touch it
glob traversals: dict[str, list[str]] = {};
# type name -> list of directly referenced type names (dependency adjacency)
glob type_deps: dict[str, list[str]] = {};
# structured compiler diagnostics
glob diagnostics: list[dict] = [];

def payload(kind: str, data: dict) -> dict {
    out = {"schema_version": SCHEMA_VERSION, "kind": kind};
    for (k, v) in data.items() {
        out[k] = v;
    }
    return out;
}

def emit(data: dict, text: bool) -> None {
    if text {
        for (k, v) in data.items() {
            if k == "schema_version" {
                continue;
            }
            print(f"{k}: {v}");
        }
    } else {
        print(json.dumps(data));
    }
}

def query_symbol(target: str) -> dict {
    if target not in symbols {
        return {};
    }
    return {
        "definition": symbols[target],
        "uses": uses_index.get(target, [])
    };
}

def query_uses(target: str) -> list[dict] {
    return uses_index.get(target, []);
}

def query_map(kind_filter: str) -> dict[str, list[str]] {
    grouped: dict[str, list[str]] = {};
    for (name, info) in symbols.items() {
        kind = info["kind"];
        if kind_filter != "" and kind != kind_filter {
            continue;
        }
        if kind not in grouped {
            grouped[kind] = [];
        }
        grouped[kind].append(name);
    }
    return grouped;
}

def query_traversers(target: str) -> list[str] {
    return traversals.get(target, []);
}

def query_slice(target: str, depth: int) -> list[str] {
    # Breadth-first walk of the type-dependency adjacency, bounded by depth.
    found: list[str] = [];
    frontier: list[str] = [target];
    level = 0;
    while level < depth and len(frontier) > 0 {
        next_frontier: list[str] = [];
        i = 0;
        while i < len(frontier) {
            cur = frontier[i];
            for dep in type_deps.get(cur, []) {
                if dep not in found and dep != target {
                    found.append(dep);
                    next_frontier.append(dep);
                }
            }
            i = i + 1;
        }
        frontier = next_frontier;
        level = level + 1;
    }
    return found;
}

def code(
    action: str = "", target: str = "", text: bool = False, depth: int = 1
) -> int {
    if action == "symbol" {
        result = query_symbol(target);
        if len(result) == 0 {
            emit(payload("symbol", {"query": target, "found": False}), text);
            return 2;
        }
        result["query"] = target;
        emit(payload("symbol", result), text);
        return 0;
    } elif action == "uses" {
        hits = query_uses(target);
        if len(hits) == 0 {
            emit(payload("uses", {"query": target, "hits": []}), text);
            return 2;
        }
        emit(payload("uses", {"query": target, "hits": hits}), text);
        return 0;
    } elif action == "map" {
        grouped = query_map(target);
        emit(payload("map", {"archetypes": grouped}), text);
        return 0;
    } elif action == "walkers" {
        names = query_traversers(target);
        if len(names) == 0 {
            emit(payload("walkers", {"node": target, "walkers": []}), text);
            return 2;
        }
        emit(payload("walkers", {"node": target, "walkers": names}), text);
        return 0;
    } elif action == "slice" {
        deps = query_slice(target, depth);
        emit(
            payload(
                "slice", {"root": target, "depth": depth, "types": deps}
            ),
            text
        );
        return 0;
    } elif action == "diag" {
        emit(payload("diag", {"diagnostics": diagnostics}), text);
        return 0;
    }
    print(
        "usage: code <symbol|uses|map|walkers|slice|diag> [target]"
    );
    return 1;
}

