"""
ECMAScript/JavaScript code generation from an ESTree-shaped dict AST.

This module converts ESTree AST records back to JavaScript source code
(unparsing). Each AST node is a plain dict with a "type" tag plus its
ESTree fields; child nodes are nested dicts and node lists are plain lists.
Generation is a single dispatch function over the "type" tag, with one
gen_* helper per node kind.

Source mapping: `line_map` collects (output_line, source_line, source_col)
triples for every node that carries a "loc" record, so consumers can map
generated lines back to their origin.
"""

glob gen_state: dict[str, int] = {"current_line": 1};
glob line_map: list[tuple] = [];

def reset_generator() -> None {
    gen_state["current_line"] = 1;
    while len(line_map) > 0 {
        line_map.pop();
    }
}

def note_lines(code: str, nd: dict) -> str {
    # Record the source mapping for this node, then advance the output
    # line counter past the code we just emitted.
    loc = nd.get("loc", {});
    if len(loc) > 0 {
        line_map.append(
            (gen_state["current_line"], loc["line"], loc["column"])
        );
    }
    gen_state["current_line"] = gen_state["current_line"] + code.count("\n");
    return code;
}

def gen_literal(nd: dict) -> str {
    v = nd["value"];
    if v is None {
        return "null";
    }
    if isinstance(v, bool) {
        return "true" if v else "false";
    }
    if isinstance(v, str) {
        return "'" + v.replace("'", "\\'") + "'";
    }
    return str(v);
}

def gen_identifier(nd: dict) -> str {
    return nd["name"];
}

def gen_binary(nd: dict, ind: str) -> str {
    lhs = generate(nd["left"], ind);
    rhs = generate(nd["right"], ind);
    return "(" + lhs + " " + nd["operator"] + " " + rhs + ")";
}

def gen_assignment(nd: dict, ind: str) -> str {
    return generate(nd["left"], ind) + " " + nd["operator"] + " "
        + generate(nd["right"], ind);
}

def gen_member(nd: dict, ind: str) -> str {
    obj_code = generate(nd["object"], ind);
    if nd.get("computed", False) {
        return obj_code + "[" + generate(nd["property"], ind) + "]";
    }
    return obj_code + "." + generate(nd["property"], ind);
}

def gen_call(nd: dict, ind: str) -> str {
    args = [generate(a, ind) for a in nd["arguments"]];
    return generate(nd["callee"], ind) + "(" + ", ".join(args) + ")";
}

def gen_array(nd: dict, ind: str) -> str {
    items = [generate(e, ind) for e in nd["elements"]];
    return "[" + ", ".join(items) + "]";
}

def gen_object(nd: dict, ind: str) -> str {
    props: list[str] = [];
    for p in nd["properties"] {
        props.append(
            generate(p["key"], ind) + ": " + generate(p["value"], ind)
        );
    }
    return "{" + ", ".join(props) + "}";
}

def gen_var_decl(nd: dict, ind: str) -> str {
    decls: list[str] = [];
    for d in nd["declarations"] {
        piece = generate(d["id"], ind);
        if d.get("init") is not None {
            piece = piece + " = " + generate(d["init"], ind);
        }
        decls.append(piece);
    }
    return ind + nd["kind"] + " " + ", ".join(decls) + ";\n";
}

def gen_block(nd: dict, ind: str) -> str {
    inner = "";
    for stmt in nd["body"] {
        inner = inner + generate(stmt, ind + "  ");
    }
    return "{\n" + inner + ind + "}";
}

def gen_if(nd: dict, ind: str) -> str {
    code = ind + "if (" + generate(nd["test"], ind) + ") "
        + gen_block(nd["consequent"], ind);
    if nd.get("alternate") is not None {
        code = code + " else " + gen_block(nd["alternate"], ind);
    }
    return code + "\n";
}

def gen_while(nd: dict, ind: str) -> str {
    return ind + "while (" + generate(nd["test"], ind) + ") "
        + gen_block(nd["body"], ind) + "\n";
}

def gen_return(nd: dict, ind: str) -> str {
    if nd.get("argument") is not None {
        return ind + "return " + generate(nd["argument"], ind) + ";\n";
    }
    return ind + "return;\n";
}

def gen_func_decl(nd: dict, ind: str) -> str {
    params = [generate(p, ind) for p in nd["params"]];
    return ind + "function " + nd["id"]["name"] + "("
        + ", ".join(params) + ") " + gen_block(nd["body"], ind) + "\n";
}

def gen_expr_stmt(nd: dict, ind: str) -> str {
    return ind + generate(nd["expression"], ind) + ";\n";
}

def gen_program(nd: dict, ind: str) -> str {
    out = "";
    for stmt in nd["body"] {
        out = out + generate(stmt, ind);
    }
    return out;
}

def generate(nd: dict, ind: str) -> str {
    if len(nd) == 0 {
        return "";
    }
    t = nd["type"];
    if t == "Program" {
        return note_lines(gen_program(nd, ind), nd);
    } elif t == "ExpressionStatement" {
        return note_lines(gen_expr_stmt(nd, ind), nd);
    } elif t == "BlockStatement" {
        return gen_block(nd, ind);
    } elif t == "EmptyStatement" {
        return note_lines(ind + ";\n", nd);
    } elif t == "ReturnStatement" {
        return note_lines(gen_return(nd, ind), nd);
    } elif t == "IfStatement" {
        return note_lines(gen_if(nd, ind), nd);
    } elif t == "WhileStatement" {
        return note_lines(gen_while(nd, ind), nd);
    } elif t == "BreakStatement" {
        return note_lines(ind + "break;\n", nd);
    } elif t == "ContinueStatement" {
        return note_lines(ind + "continue;\n", nd);
    } elif t == "FunctionDeclaration" {
        return note_lines(gen_func_decl(nd, ind), nd);
    } elif t == "VariableDeclaration" {
        return note_lines(gen_var_decl(nd, ind), nd);
    } elif t == "Identifier" {
        return gen_identifier(nd);
    } elif t == "Literal" {
        return gen_literal(nd);
    } elif t == "ThisExpression" {
        return "this";
    } elif t == "ArrayExpression" {
        return gen_array(nd, ind);
    } elif t == "ObjectExpression" {
        return gen_object(nd, ind);
    } elif t == "BinaryExpression" {
        return gen_binary(nd, ind);
    } elif t == "LogicalExpression" {
        return gen_binary(nd, ind);
    } elif t == "AssignmentExpression" {
        return gen_assignment(nd, ind);
    } elif t == "MemberExpression" {
        return gen_member(nd, ind);
    } elif t == "CallExpression" {
        return gen_call(nd, ind);
    }
    return "/* unsupported: " + t + " */";
}

def es_to_js(nd: dict) -> str {
    reset_generator();
    return generate(nd, "");
}

def es_to_js_with_map(nd: dict) -> tuple {
    code = es_to_js(nd);
    return (code, list(line_map));
}

