# Statement store: id -> {"kind", "label", plus structural fields:
#   "then"/"orelse" (if), "body" (while), "syms" (condition symbols)}
glob stmts: dict[str, dict] = {};
# CFG adjacency: outgoing and incoming edges per statement id.
glob bb_out: dict[str, list[str]] = {};
glob bb_in: dict[str, list[str]] = {};
# Condition statement id -> symbols its test reads.
glob affected_symbols: dict[str, list[str]] = {};

def add_stmt(sid: str, kind: str, label: str) -> dict {
    rec = {
        "kind": kind, "label": label,
        "then": [], "orelse": [], "body": [], "syms": []
    };
    stmts[sid] = rec;
    return rec;
}

def link_bbs(source: str, target: str) -> None {
    outs = bb_out.setdefault(source, []);
    if target not in outs {
        outs.append(target);
    }
    ins = bb_in.setdefault(target, []);
    if source not in ins {
        ins.append(source);
    }
}

def is_terminal(sid: str) -> bool {
    return stmts[sid]["kind"] in ("break", "continue", "return", "raise");
}

def collect_affected_symbols(sid: str) -> None {
    affected_symbols[sid] = list(stmts[sid]["syms"]);
}

def wire_stmt(
    sid: str, follow: str, loop_header: str, loop_follow: str
) -> None {
    kind = stmts[sid]["kind"];
    if kind == "return" or kind == "raise" {
        return;
    }
    if kind == "break" {
        if loop_follow != "" {
            link_bbs(sid, loop_follow);
        }
        return;
    }
    if kind == "continue" {
        if loop_header != "" {
            link_bbs(sid, loop_header);
        }
        return;
    }
    if kind == "if" {
        collect_affected_symbols(sid);
        then_body = stmts[sid]["then"];
        else_body = stmts[sid]["orelse"];
        if len(then_body) > 0 {
            link_bbs(sid, then_body[0]);
            wire_seq(then_body, follow, loop_header, loop_follow);
        } elif follow != "" {
            link_bbs(sid, follow);
        }
        if len(else_body) > 0 {
            link_bbs(sid, else_body[0]);
            wire_seq(else_body, follow, loop_header, loop_follow);
        } elif follow != "" {
            # No else branch: the false edge falls through.
            link_bbs(sid, follow);
        }
        return;
    }
    if kind == "while" {
        collect_affected_symbols(sid);
        body = stmts[sid]["body"];
        if len(body) > 0 {
            link_bbs(sid, body[0]);
            # Body tails loop back to the header; break exits to `follow`.
            wire_seq(body, sid, sid, follow);
        } else {
            link_bbs(sid, sid);
        }
        if follow != "" {
            link_bbs(sid, follow);
        }
        return;
    }
    # Plain statement: sequential edge only.
    if follow != "" {
        link_bbs(sid, follow);
    }
}

def wire_seq(
    body: list[str], follow: str, loop_header: str, loop_follow: str
) -> None {
    i = 0;
    while i < len(body) {
        nxt = body[i + 1] if i + 1 < len(body) else follow;
        wire_stmt(body[i], nxt, loop_header, loop_follow);
        i = i + 1;
    }
}

def build_cfg(module_body: list[str]) -> None {
    wire_seq(module_body, "", "", "");
}

def coalesce_basic_blocks() -> list[list[str]] {
    # A leader starts a block: no single predecessor, or its predecessor
    # branches. Follow single-out/single-in chains from each leader.
    blocks: list[list[str]] = [];
    claimed: list[str] = [];
    for sid in stmts.keys() {
        ins = bb_in.get(sid, []);
        is_leader = len(ins) != 1
            or len(bb_out.get(ins[0], [])) != 1;
        if not is_leader or sid in claimed {
            continue;
        }
        block = [sid];
        claimed.append(sid);
        cur = sid;
        while len(bb_out.get(cur, [])) == 1 {
            nxt = bb_out[cur][0];
            if len(bb_in.get(nxt, [])) != 1 or nxt in claimed {
                break;
            }
            block.append(nxt);
            claimed.append(nxt);
            cur = nxt;
        }
        blocks.append(block);
    }
    return blocks;
}

def node_label(sid: str) -> str {
    return stmts[sid]["label"];
}

def printgraph_cfg() -> str {
    blocks = coalesce_basic_blocks();
    owner: dict[str, int] = {};
    for (bi, block) in enumerate(blocks) {
        for sid in block {
            owner[sid] = bi;
        }
    }
    lines: list[str] = ["digraph cfg {"];
    for (bi, block) in enumerate(blocks) {
        labels = "\\n".join([node_label(s) for s in block]);
        lines.append(f'  bb{bi} [label="{labels}"];');
    }
    seen: list[str] = [];
    for (src, targets) in bb_out.items() {
        for tgt in targets {
            key = f"{owner[src]}->{owner[tgt]}";
            same_block = owner[src] == owner[tgt]
                and stmts[src]["kind"] not in ("while", "if");
            if same_block or key in seen {
                continue;
            }
            seen.append(key);
            lines.append(f"  bb{owner[src]} -> bb{owner[tgt]};");
        }
    }
    lines.append("}");
    return "\n".join(lines);
}

