}

impl PyJacAstLinkPass.exit_archetype(nd: uni.Archetype) -> None {
    self.link_jac_py_nodes(jac_node=nd.name, py_nodes=nd.gen.py_ast);
    if isinstance(nd.body, uni.ImplDef) {
