"""Jac-to-Python AST linking, dict edition.

Jac AST nodes and generated Python AST nodes both live in flat dict stores
keyed by string id. Linking writes two plain maps instead of touching object
attributes: each jac record gets a "py_ast" list of python node ids, and each
python record keeps a "jac_link" back-reference list. One `exit_*` function
per jac node kind mirrors the pass's exit handlers: each reads the record's
structural fields (child ids, target lists, generated python ids) and calls
`link_jac_py_nodes` with the same guards as the original pass -- including
skipping client-context nodes and the length guards on nonlocal/global
target lists.
"""

glob jac_nodes: dict[str, dict] = {};
glob py_nodes: dict[str, dict] = {};
# symbol name -> {"decl": jac node id, "uses": [jac name-node ids]}
glob symbols: dict[str, dict] = {};

def add_jac(nid: str, kind: str, fields: dict) -> None {
    rec = {"kind": kind, "code_context": "server", "py_ast": []};
    for (k, v) in fields.items() {
        rec[k] = v;
    }
    jac_nodes[nid] = rec;
}

def add_py(pid: str, kind: str) -> None {
    py_nodes[pid] = {"kind": kind, "jac_link": []};
}

"""Link a jac node record to its generated python node records."""
def link_jac_py_nodes(jac_id: str, py_ids: list[str]) -> None {
    if jac_nodes[jac_id]["code_context"] == "client" {
        return;
    }
    jac_nodes[jac_id]["py_ast"] = list(py_ids);
    for pid in py_ids {
        back = py_nodes[pid]["jac_link"];
        if isinstance(back, list) {
            back.append(jac_id);
        }
    }
}

def exit_atom_trailer(nid: str) -> None {
    rec = jac_nodes[nid];
    if rec["is_attr"] and rec["right_is_symbol"] {
        right = jac_nodes[rec["right"]];
        link_jac_py_nodes(right["name_spec"], rec["gen_py"]);
    }
}

def exit_k_w_pair(nid: str) -> None {
    rec = jac_nodes[nid];
    if rec.get("key", "") != "" {
        link_jac_py_nodes(rec["key"], rec["gen_py"]);
    }
}

def exit_non_local_stmt(nid: str) -> None {
    rec = jac_nodes[nid];
    if len(rec["gen_py"]) == 0 or len(rec["gen_py"]) < len(rec["targets"]) {
        return;
    }
    for (x, y) in enumerate(rec["targets"]) {
        link_jac_py_nodes(y, [rec["gen_py"][x]]);
    }
}

def exit_global_stmt(nid: str) -> None {
    rec = jac_nodes[nid];
    if len(rec["gen_py"]) == 0 or len(rec["gen_py"]) < len(rec["targets"]) {
        return;
    }
    for (x, y) in enumerate(rec["targets"]) {
        link_jac_py_nodes(y, [rec["gen_py"][x]]);
    }
}

def exit_expr_as_item(nid: str) -> None {
    rec = jac_nodes[nid];
    link_jac_py_nodes(rec["expr"], rec["gen_py"]);
    if rec.get("alias", "") != "" {
        link_jac_py_nodes(rec["alias"], rec["gen_py"]);
    }
}

def exit_except(nid: str) -> None {
    rec = jac_nodes[nid];
    if rec.get("name", "") != "" {
        link_jac_py_nodes(rec["name"], rec["gen_py"]);
    }
}

def exit_param_var(nid: str) -> None {
    rec = jac_nodes[nid];
    link_jac_py_nodes(rec["name"], rec["gen_py"]);
}

def exit_impl_def(nid: str) -> None {
    rec = jac_nodes[nid];
    for t in rec["targets"] {
        sym_name = jac_nodes[t].get("sym", "");
        if sym_name != "" {
            decl_id = symbols[sym_name]["decl"];
            decl_py = jac_nodes[decl_id]["py_ast"];
            link_jac_py_nodes(t, decl_py);
            link_jac_py_nodes(jac_nodes[t]["name_spec"], decl_py);
        }
    }
    decl_link = rec.get("decl_link", "");
    if decl_link != "" and jac_nodes[decl_link]["kind"] == "ability" {
        # Match impl-spec params to declaration params by name.
        for sp in rec.get("spec_params", []) {
            for dp in jac_nodes[decl_link].get("params", []) {
                if jac_nodes[sp]["sym_name"] == jac_nodes[dp]["sym_name"] {
                    link_jac_py_nodes(sp, jac_nodes[dp]["py_ast"]);
                    link_jac_py_nodes(
                        jac_nodes[sp]["name"],
                        jac_nodes[jac_nodes[dp]["name"]]["py_ast"]
                    );
                }
            }
        }
        spec_ret = rec.get("spec_return", "");
        decl_ret = jac_nodes[decl_link].get("return_type", "");
        if spec_ret != "" and decl_ret != "" {
            link_jac_py_nodes(spec_ret, jac_nodes[decl_ret]["py_ast"]);
        }
        for t in rec["targets"] {
            sym_name = jac_nodes[t].get("sym", "");
            if sym_name != "" {
                symbols[sym_name]["uses"].append(jac_nodes[t]["name_spec"]);
            }
        }
    }
}

def exit_ability(nid: str) -> None {
    rec = jac_nodes[nid];
    link_jac_py_nodes(rec["name_ref"], rec["gen_py"]);
    body = rec.get("body", "");
    if body != "" and jac_nodes[body]["kind"] == "impl_def" {
        link_jac_py_nodes(body, rec["gen_py"]);
    }
}

def exit_enum(nid: str) -> None {
    rec = jac_nodes[nid];
    body = rec.get("body", "");
    if body != "" and jac_nodes[body]["kind"] == "impl_def" {
        link_jac_py_nodes(body, rec["gen_py"]);
    }
}

def exit_type_alias(nid: str) -> None {
    rec = jac_nodes[nid];
    link_jac_py_nodes(rec["name"], rec["gen_py"]);
}

def exit_archetype(nid: str) -> None {
    rec = jac_nodes[nid];
    link_jac_py_nodes(rec["name"], rec["gen_py"]);
    body = rec.get("body", "");
    if body != "" and jac_nodes[body]["kind"] == "impl_def" {
        link_jac_py_nodes(body, rec["gen_py"]);
    }
}

def exit_module_path(nid: str) -> None {
    rec = jac_nodes[nid];
    if rec.get("alias", "") != "" {
        link_jac_py_nodes(rec["alias"], rec["gen_py"]);
    }
}

