"""Type layout analysis, dict edition.

Computes class hierarchy, C3 MRO, field layout, and vtable structure for a
set of archetype records. Archetypes are plain dicts in a flat store; the
class hierarchy is a `class_parents` adjacency map (class name -> list of
parent names). Results land in a registry of plain dicts that any backend
(Python, ES, Native/LLVM) can query:

- `layouts`: class name -> {fields, field_index, methods, method_index,
  mro, parents, has_vtable, parent_field_start}
- `mro_order`: class name -> its C3 linearization
- `topo_order`: parents-before-children ordering of all classes

`obj` fields must resolve to a layout-compatible primitive, another declared
archetype, a typed collection (list[T], dict[K,V], set[T]) whose element
types are also layout-compatible, or a callable with explicit signature
(function pointer). Violations are collected as warnings.
"""

glob LAYOUT_COMPATIBLE_PRIMITIVES: set[str] = {
    "int", "float", "bool", "str", "bytes",
    "i8", "u8", "i16", "u16", "i32", "u32", "i64", "u64", "f32", "f64"
};

# Archetype store: name -> {"arch_type", "parents", "fields", "methods"}
# where fields is a list of {"name", "type_tag", "is_func_ptr"} records and
# methods is a list of method names in declaration order.
glob archetypes: dict[str, dict] = {};

# Registry (all plain dicts/lists).
glob layouts: dict[str, dict] = {};
glob class_parents: dict[str, list[str]] = {};
glob mro_order: dict[str, list[str]] = {};
glob topo_order: list[str] = [];
glob warnings: list[str] = [];

def declare(
    name: str, arch_type: str, parents: list[str],
    fields: list[dict], methods: list[str]
) -> None {
    archetypes[name] = {
        "arch_type": arch_type, "parents": parents,
        "fields": fields, "methods": methods
    };
}

def build_hierarchy() -> None {
    for (name, arch) in archetypes.items() {
        class_parents[name] = [
            p for p in arch["parents"] if p in archetypes
        ];
    }
}

def compute_c3_mro(class_name: str) -> list[str] {
    if class_name in mro_order {
        return mro_order[class_name];
    }
    parents = class_parents.get(class_name, []);
    result: list[str] = [class_name];
    if len(parents) == 0 {
        mro_order[class_name] = result;
        return result;
    }
    # C3 merge of parent linearizations plus the parent list itself.
    seqs: list[list[str]] = [list(compute_c3_mro(p)) for p in parents];
    seqs.append(list(parents));
    while True {
        seqs = [s for s in seqs if len(s) > 0];
        if len(seqs) == 0 {
            break;
        }
        picked = "";
        for s in seqs {
            head = s[0];
            in_tail = False;
            for other in seqs {
                if head in other[1:] {
                    in_tail = True;
                }
            }
            if not in_tail {
                picked = head;
                break;
            }
        }
        if picked == "" {
            warnings.append(
                f"E5030: inconsistent MRO for {class_name}"
            );
            break;
        }
        result.append(picked);
        for s in seqs {
            if len(s) > 0 and s[0] == picked {
                s.pop(0);
            }
        }
    }
    mro_order[class_name] = result;
    return result;
}

def topo_sort() -> None {
    visited: list[str] = [];
    order: list[str] = [];
    for name in archetypes.keys() {
        _topo_visit(name, visited, order);
    }
    for name in order {
        topo_order.append(name);
    }
}

def _topo_visit(name: str, visited: list[str], order: list[str]) -> None {
    if name in visited {
        return;
    }
    visited.append(name);
    for p in class_parents.get(name, []) {
        _topo_visit(p, visited, order);
    }
    order.append(name);
}

def build_layout(name: str) -> None {
    mro = compute_c3_mro(name);
    fields: list[dict] = [];
    field_index: dict[str, int] = {};
    parent_field_start: dict[str, int] = {};
    # Base-most classes lay their fields out first.
    for owner in reversed(mro) {
        parent_field_start[owner] = len(fields);
        for f in archetypes[owner]["fields"] {
            if f["name"] in field_index {
                continue;  # redeclared field keeps its slot
            }
            field_index[f["name"]] = len(fields);
            fields.append({
                "name": f["name"], "index": len(fields),
                "type_tag": f["type_tag"], "owner": owner,
                "is_func_ptr": f.get("is_func_ptr", False)
            });
        }
    }
    methods: list[dict] = [];
    method_index: dict[str, int] = {};
    for owner in reversed(mro) {
        for m in archetypes[owner]["methods"] {
            if m in method_index {
                # Override: same vtable slot, new owner.
                methods[method_index[m]]["owner"] = owner;
            } else {
                method_index[m] = len(methods);
                methods.append({
                    "name": m, "index": len(methods), "owner": owner
                });
            }
        }
    }
    layouts[name] = {
        "name": name,
        "arch_type": archetypes[name]["arch_type"],
        "parents": class_parents.get(name, []),
        "mro": mro,
        "fields": fields,
        "field_index": field_index,
        "methods": methods,
        "method_index": method_index,
        "has_vtable": len(methods) > 0,
        "parent_field_start": parent_field_start
    };
}

def is_layout_compatible_type(type_tag: str) -> bool {
    if type_tag in LAYOUT_COMPATIBLE_PRIMITIVES or type_tag in archetypes {
        return True;
    }
    for prefix in ("list[", "dict[", "set[") {
        if type_tag.startswith(prefix) and type_tag.endswith("]") {
            inner = type_tag[len(prefix):-1];
            parts = [p.strip() for p in inner.split(",")];
            ok = True;
            for part in parts {
                if not is_layout_compatible_type(part) {
                    ok = False;
                }
            }
            return ok;
        }
    }
    return False;
}

def validate_obj_fields(name: str) -> None {
    arch = archetypes[name];
    if arch["arch_type"] != "obj" {
        return;
    }
    for f in arch["fields"] {
        if f.get("is_func_ptr", False) {
            continue;
        }
        if not is_layout_compatible_type(f["type_tag"]) {
            warnings.append(
                f"W5031: {name}.{f['name']}: type `{f['type_tag']}` has no "
                + "fixed-size native layout"
            );
        }
    }
}

def run_layout_pass() -> None {
    build_hierarchy();
    topo_sort();
    for name in topo_order {
        build_layout(name);
        validate_obj_fields(name);
    }
}

def get_field_index(class_name: str, field_name: str) -> int {
    layout = layouts.get(class_name, {});
    if len(layout) == 0 {
        return -1;
    }
    return layout["field_index"].get(field_name, -1);
}

def get_method_slot(class_name: str, method_name: str) -> int {
    layout = layouts.get(class_name, {});
    if len(layout) == 0 {
        return -1;
    }
    return layout["method_index"].get(method_name, -1);
}

def is_subclass(child: str, parent: str) -> bool {
    # Breadth-first walk up the parent adjacency.
    queue: list[str] = [child];
    seen: list[str] = [];
    while len(queue) > 0 {
        cur = queue.pop(0);
        if cur == parent {
            return True;
        }
        if cur in seen {
            continue;
        }
        seen.append(cur);
        for p in class_parents.get(cur, []) {
            queue.append(p);
        }
    }
    return False;
}

def is_primary_ancestor(child: str, ancestor: str) -> bool {
    # Follow only first parents (the primary chain).
    cur = child;
    while cur != "" {
        if cur == ancestor {
            return True;
        }
        parents = class_parents.get(cur, []);
        cur = parents[0] if len(parents) > 0 else "";
    }
    return False;
}

