    "LtE": ("LTE", "<="), "Gt": ("GT", ">"), "GtE": ("GTE", ">="),
    "Is": ("KW_IS", "is"), "IsNot": ("KW_ISN", "is not"),
    "In": ("KW_IN", "in"), "NotIn": ("KW_NIN", "not in")
};

glob AUG_OPS: dict[str, str] = {
    "Add": "+=", "Sub": "-=", "Mult": "*=", "Div": "/=",
    "FloorDiv": "//=", "Mod": "%=", "Pow": "**=", "LShift": "<<=",
    "RShift": ">>=", "BitAnd": "&=", "BitOr": "|=", "BitXor": "^="
};

def init_converter(mod_path: str, orig_src: str) -> None {
    conv_state["mod_path"] = mod_path;
    conv_state["orig_src"] = orig_src;
    conv_state["source_lines"] = orig_src.split("\n");
    conv_state["in_type_annotation"] = False;
    conv_state["in_match_pattern"] = False;
    conv_state["in_fstring_expr"] = False;
}

def get_source_segment(nd: dict) -> str {
    lines = conv_state["source_lines"];
    lineno = nd.get("lineno", 0);
    if lineno < 1 or lineno > len(lines) {
        return "";
    }
    return lines[lineno - 1].strip();
}

def nu(rec: dict, nd: dict) -> dict {
    # Stamp source location from the python node onto the jac record.
    rec["loc"] = {
        "path": conv_state["mod_path"], "line": nd.get("lineno", 0)
    };
    return rec;
}

def operator(nd: dict) -> dict {
    (tok, value) = OP_TOKENS[nd["type"]];
    return {"kind": "token", "tok": tok, "value": value};
}

def aug_op_map(nd: dict) -> str {
    return AUG_OPS[nd["type"]];
}

def proc_name(nd: dict) -> dict {
    return nu({"kind": "name", "value": nd["id"]}, nd);
}

def proc_constant(nd: dict) -> dict {
    return nu({"kind": "literal", "value": nd["value"]}, nd);
}

def proc_arg(nd: dict) -> dict {
    annotation: dict = {};
    if len(nd.get("annotation", {})) > 0 {
        conv_state["in_type_annotation"] = True;
        annotation = convert(nd["annotation"]);
        conv_state["in_type_annotation"] = False;
    }
    return nu(
        {"kind": "param_var", "name": nd["arg"], "type": annotation}, nd
    );
}

def proc_arguments(nd: dict) -> dict {
    return {
        "kind": "func_signature",
        "params": [proc_arg(a) for a in nd.get("args", [])]
    };
}

def proc_bin_op(nd: dict) -> dict {
    return nu({
        "kind": "binary_expr",
        "op": operator(nd["op"]),
        "left": convert(nd["left"]),
        "right": convert(nd["right"])
    }, nd);
}

def proc_bool_op(nd: dict) -> dict {
    return nu({
        "kind": "bool_expr",
        "op": operator(nd["op"]),
        "values": [convert(v) for v in nd["values"]]
    }, nd);
}

def proc_compare(nd: dict) -> dict {
    return nu({
        "kind": "compare_expr",
        "left": convert(nd["left"]),
        "ops": [operator(o) for o in nd["ops"]],
        "rights": [convert(c) for c in nd["comparators"]]
    }, nd);
}

def proc_call(nd: dict) -> dict {
    return nu({
        "kind": "func_call",
        "target": convert(nd["func"]),
        "args": [convert(a) for a in nd.get("args", [])],
        "kwargs": [
            {"kind": "kw_pair", "key": kw["arg"], "value": convert(kw["value"])}
            for kw in nd.get("keywords", [])
        ]
    }, nd);
}

def proc_attribute(nd: dict) -> dict {
    return nu({
        "kind": "atom_trailer", "is_attr": True,
        "target": convert(nd["value"]),
        "right": {"kind": "name", "value": nd["attr"]}
    }, nd);
}

def proc_list(nd: dict) -> dict {
    return nu(
        {"kind": "list_val", "values": [convert(e) for e in nd["elts"]]}, nd
    );
}

def proc_dict(nd: dict) -> dict {
    pairs: list[dict] = [];
    for (i, k) in enumerate(nd["keys"]) {
        pairs.append(
            {"key": convert(k), "value": convert(nd["values"][i])}
        );
    }
    return nu({"kind": "dict_val", "pairs": pairs}, nd);
}

def proc_assign(nd: dict) -> dict {
    return nu({
        "kind": "assignment",
        "targets": [convert(t) for t in nd["targets"]],
        "value": convert(nd["value"])
    }, nd);
}

def proc_aug_assign(nd: dict) -> dict {
    return nu({
        "kind": "assignment", "aug_op": aug_op_map(nd["op"]),
        "targets": [convert(nd["target"])],
        "value": convert(nd["value"])
    }, nd);
}

def proc_ann_assign(nd: dict) -> dict {
    conv_state["in_type_annotation"] = True;
    type_tag = convert(nd["annotation"]);
    conv_state["in_type_annotation"] = False;
    value: dict = {};
    if len(nd.get("value", {})) > 0 {
        value = convert(nd["value"]);
    }
    return nu({
        "kind": "assignment", "targets": [convert(nd["target"])],
        "type": type_tag, "value": value
    }, nd);
}

def proc_return(nd: dict) -> dict {
    expr: dict = {};
    if len(nd.get("value", {})) > 0 {
        expr = convert(nd["value"]);
    }
    return nu({"kind": "return_stmt", "expr": expr}, nd);
}

def proc_expr(nd: dict) -> dict {
    return nu({"kind": "expr_stmt", "expr": convert(nd["value"])}, nd);
}

def proc_pass(nd: dict) -> dict {
    return nu({"kind": "semi"}, nd);
}

def proc_if(nd: dict) -> dict {
    return nu({
        "kind": "if_stmt",
        "condition": convert(nd["test"]),
        "body": [convert(s) for s in nd["body"]],
        "else_body": [convert(s) for s in nd.get("orelse", [])]
    }, nd);
}

def proc_while(nd: dict) -> dict {
    return nu({
        "kind": "while_stmt",
        "condition": convert(nd["test"]),
        "body": [convert(s) for s in nd["body"]]
    }, nd);
}

def proc_for(nd: dict) -> dict {
    return nu({
        "kind": "in_for_stmt",
        "target": convert(nd["target"]),
        "collection": convert(nd["iter"]),
        "body": [convert(s) for s in nd["body"]]
    }, nd);
}

def proc_function_def(nd: dict) -> dict {
    signature = proc_arguments(nd["args"]);
    if len(nd.get("returns", {})) > 0 {
        conv_state["in_type_annotation"] = True;
        signature["return_type"] = convert(nd["returns"]);
        conv_state["in_type_annotation"] = False;
    }
    body = [convert(s) for s in nd["body"]];
    convert_to_doc(body);
    return nu({
        "kind": "ability", "name": nd["name"],
        "is_async": nd.get("is_async", False),
        "signature": signature, "body": body,
        "src": get_source_segment(nd)
    }, nd);
}

def proc_class_def(nd: dict) -> dict {
    base_names = [b.get("id", "") for b in nd.get("bases", [])];
    body = [convert(s) for s in nd["body"]];
    convert_to_doc(body);
    if "Enum" in base_names {
        return nu(
            {"kind": "enum", "name": nd["name"], "body": body}, nd
        );
    }
    return nu({
        "kind": "archetype", "arch_type": "obj", "name": nd["name"],
        "bases": base_names, "body": body
    }, nd);
}

def convert_to_doc(body: list[dict]) -> None {
    # A leading string expression becomes the record's docstring.
    if len(body) > 0 and body[0]["kind"] == "expr_stmt" {
        expr = body[0]["expr"];
        if expr["kind"] == "literal" and isinstance(expr["value"], str) {
            body[0] = {"kind": "doc", "value": expr["value"]};
        }
    }
}

def extract_with_entry(body: list[dict]) -> list[dict] {
    # Declarations stay at module level; runs of loose statements are
    # gathered into `with entry` (module_code) blocks.
    out: list[dict] = [];
    pending: list[dict] = [];
    decl_kinds = ("ability", "archetype", "enum", "doc");
    for rec in body {
        if rec["kind"] in decl_kinds {
            if len(pending) > 0 {
                out.append({"kind": "module_code", "body": list(pending)});
                pending.clear();
            }
            out.append(rec);
        } else {
            pending.append(rec);
        }
    }
    if len(pending) > 0 {
        out.append({"kind": "module_code", "body": list(pending)});
    }
    return out;
}

def proc_module(nd: dict) -> dict {
    body = [convert(s) for s in nd["body"]];
    convert_to_doc(body);
    return {
        "kind": "module", "path": conv_state["mod_path"],
        "body": extract_with_entry(body)
    };
}

def convert(nd: dict) -> dict {
    t = nd["type"];
    if t == "Module" {
        return proc_module(nd);
    } elif t == "FunctionDef" or t == "AsyncFunctionDef" {
        nd["is_async"] = t == "AsyncFunctionDef";
        return proc_function_def(nd);
    } elif t == "ClassDef" {
        return proc_class_def(nd);
    } elif t == "Return" {
        return proc_return(nd);
    } elif t == "Assign" {
        return proc_assign(nd);
    } elif t == "AugAssign" {
        return proc_aug_assign(nd);
    } elif t == "AnnAssign" {
        return proc_ann_assign(nd);
    } elif t == "For" {
        return proc_for(nd);
    } elif t == "While" {
        return proc_while(nd);
    } elif t == "If" {
        return proc_if(nd);
    } elif t == "Expr" {
        return proc_expr(nd);
    } elif t == "Pass" {
        return proc_pass(nd);
    } elif t == "Call" {
        return proc_call(nd);
    } elif t == "Attribute" {
        return proc_attribute(nd);
    } elif t == "BinOp" {
        return proc_bin_op(nd);
    } elif t == "BoolOp" {
        return proc_bool_op(nd);
    } elif t == "Compare" {
        return proc_compare(nd);
    } elif t == "Name" {
        return proc_name(nd);
    } elif t == "Constant" {
        return proc_constant(nd);
    } elif t == "List" {
        return proc_list(nd);
    } elif t == "Dict" {
        return proc_dict(nd);
    }
    return {"kind": "unsupported", "py_type": t};
}

def transform(py_module: dict, mod_path: str, src: str) -> dict {
    init_converter(mod_path, src);
    return convert(py_module);
}

def summarize(rec: dict, depth: int) -> None {
    pad = "  " * depth;
    kind = rec["kind"];
    name = rec.get("name", rec.get("value", ""));
    print(f"{pad}{kind} {name}");
    for child in rec.get("body", []) {
        summarize(child, depth + 1);
    }
}

