"""Static analysis, rewritten without the pass/visitor machinery.

The module under analysis is a set of flat dict stores instead of a tree of
pass-visited nodes: a symbol table dict, a reference list, a statement store,
and a control-flow adjacency map. The analysis detects:
1. Unused variables - symbols defined but never referenced
2. Undefined variables - name references that fail to resolve (with a
   case-based suggestion when a differently-cased symbol exists)
3. Unreachable code - statements with no incoming control-flow path from the
   entry statement, found by a plain BFS over the cfg adjacency dict
4. Redundant imports - the same module imported more than once

All analysis runs in bulk over the stores from run_analysis(); there is no
node-by-node traversal object.
"""

glob symbols: dict[str, dict] = {};
glob references: list[dict] = [];
glob statements: dict[str, dict] = {};
glob cfg_edges: dict[str, list[str]] = {};
glob import_names: list[str] = [];
glob diagnostics: list[str] = [];

def define_symbol(name: str, line: int) -> None {
    symbols[name] = {"line": line};
}

def reference_name(name: str, line: int) -> None {
    references.append({"name": name, "line": line});
}

def add_statement(sid: str, line: int, text: str) -> None {
    statements[sid] = {"line": line, "text": text};
}

def add_flow(src_sid: str, dst_sid: str) -> None {
    if src_sid not in cfg_edges {
        cfg_edges[src_sid] = [];
    }
    cfg_edges[src_sid].append(dst_sid);
}

def check_unused_symbols() -> None {
    for name in symbols.keys() {
        used = False;
        i = 0;
        while i < len(references) {
            if references[i]["name"] == name {
                used = True;
            }
            i = i + 1;
        }
        if not used {
            line = symbols[name]["line"];
            diagnostics.append(f"W1103 line {line}: symbol '{name}' defined but never used");
        }
    }
}

def literal_case_suggestion(name: str) -> str {
    for known in symbols.keys() {
        if known.lower() == name.lower() and known != name {
            return known;
        }
    }
    return "";
}

def check_undefined_names() -> None {
    i = 0;
    while i < len(references) {
        ref = references[i];
        if ref["name"] not in symbols {
            line = ref["line"];
            name = ref["name"];
            suggestion = literal_case_suggestion(name);
            if suggestion != "" {
                diagnostics.append(f"E2018 line {line}: undefined name {name} - did you mean {suggestion}?");
            } else {
                diagnostics.append(f"E2018 line {line}: undefined name '{name}'");
            }
        }
        i = i + 1;
    }
}

def check_unreachable_code(entry_sid: str) -> None {
    reached: list[str] = [];
    queue: list[str] = [entry_sid];
    while len(queue) > 0 {
        cur = queue.pop(0);
        if cur in reached {
            continue;
        }
        reached.append(cur);
        successors = cfg_edges.get(cur, []);
        i = 0;
        while i < len(successors) {
            queue.append(successors[i]);
            i = i + 1;
        }
    }
    for sid in statements.keys() {
        if sid not in reached {
            line = statements[sid]["line"];
            text = statements[sid]["text"];
            diagnostics.append(f"W2058 line {line}: unreachable statement '{text}'");
        }
    }
}

def check_redundant_imports() -> None {
    counts: dict[str, int] = {};
    i = 0;
    while i < len(import_names) {
        name = import_names[i];
        counts[name] = counts.get(name, 0) + 1;
        i = i + 1;
    }
    for name in counts.keys() {
        if counts[name] > 1 {
            n = counts[name];
            diagnostics.append(f"W2074 module '{name}' imported {n} times");
        }
    }
}

def run_analysis(entry_sid: str) -> list[str] {
    check_unused_symbols();
    check_undefined_names();
    check_unreachable_code(entry_sid);
    check_redundant_imports();
    return diagnostics;
}

