"""Pre-computes backend-neutral analysis on a dict-based AST so codegen stays
pure code generation, rewritten without the pass/visitor machinery.

The tree is a flat dict store keyed by id with a child adjacency map. A plain
pre-order stack walk dispatches on each record's "kind" tag:
- every "name" record gets a js_decl_kind hint derived from its parent kind
- OSP-only constructs (visit/disengage/report stmts, edge op refs, disconnect
  ops, typed ctx blocks) and dynamic constructs (yield, lambda, py inline)
  clear the module's native_compat flag and record the reason
- client/server blocks and module code stamp a codespace context on their
  subtree roots
The module record is finalized at the end of the walk (the old exit_module).
"""

glob nodes: dict[str, dict] = {};
glob children: dict[str, list[str]] = {};
glob parent_of: dict[str, str] = {};

def add_tree_node(nid: str, kind: str, parent_id: str) -> None {
    nodes[nid] = {"kind": kind};
    children[nid] = [];
    if parent_id != "" {
        children[parent_id].append(nid);
        parent_of[nid] = parent_id;
    }
}

def enrich_name(nid: str) -> None {
    parent_kind = "";
    if nid in parent_of {
        parent_kind = nodes[parent_of[nid]]["kind"];
    }
    if parent_kind == "param_var" {
        nodes[nid]["js_decl_kind"] = "param";
    } elif parent_kind == "assignment" {
        nodes[nid]["js_decl_kind"] = "let";
    } elif parent_kind == "global_vars" {
        nodes[nid]["js_decl_kind"] = "var";
    } else {
        nodes[nid]["js_decl_kind"] = "ref";
    }
}

def mark_native_incompat(module_id: str, reason: str) -> None {
    gen = nodes[module_id]["gen"];
    gen["native_compat"] = False;
    gen["incompat_reasons"].append(reason);
}

def stamp_context(nid: str, context: str) -> None {
    nodes[nid]["context"] = context;
}

def run_enrich_pass(module_id: str) -> None {
    # before_pass: seed the module's gen record.
    nodes[module_id]["gen"] = {"native_compat": True, "incompat_reasons": []};
    osp_kinds = ["visit_stmt", "disengage_stmt", "report_stmt", "edge_op_ref", "disconnect_op", "typed_ctx_block"];
    dynamic_kinds = ["yield_expr", "lambda_expr", "py_inline_code"];
    stack: list[str] = [module_id];
    while len(stack) > 0 {
        cur = stack.pop();
        kind = nodes[cur]["kind"];
        if kind == "name" {
            enrich_name(cur);
        } elif kind in osp_kinds {
            mark_native_incompat(module_id, kind);
        } elif kind in dynamic_kinds {
            mark_native_incompat(module_id, kind);
