"""Unparse for a dict-based AST.

Serializes AST records back to source strings, rewritten without the
pass/visitor machinery: nodes are dict records {"kind", "fields", "value"} in
a flat store with child ids held in field lists, and generated source lives
in a plain gen map dict[str, str] instead of node.gen.jac. A single
post-order walk (children before parents, via a reversed pre-order stack
collection) replaces the per-kind exit_* methods; each kind's serializer
reads its children's already-generated strings out of the gen map.
"""

glob nodes: dict[str, dict] = {};
glob gen: dict[str, str] = {};

def add_ast_node(nid: str, kind: str, value: str, fields: dict[str, list[str]]) -> None {
    nodes[nid] = {"kind": kind, "value": value, "fields": fields};
}

def field_ids(nid: str, field: str) -> list[str] {
    return nodes[nid]["fields"].get(field, []);
}

def first_gen(nid: str, field: str) -> str {
    ids = field_ids(nid, field);
    if len(ids) == 0 {
        return "";
    }
    return gen[ids[0]];
}

def comma_sep(ids: list[str]) -> str {
    parts: list[str] = [];
    i = 0;
    while i < len(ids) {
        parts.append(gen[ids[i]]);
        i = i + 1;
    }
    return ", ".join(parts);
}

def joined(ids: list[str], sep: str) -> str {
    parts: list[str] = [];
    i = 0;
    while i < len(ids) {
        parts.append(gen[ids[i]]);
        i = i + 1;
    }
    return sep.join(parts);
}

def unparse_node(nid: str) -> None {
    rec = nodes[nid];
    kind = rec["kind"];
    if kind == "token" or kind == "name" or kind == "int" or kind == "float" or kind == "bool" or kind == "null" {
        gen[nid] = rec["value"];
    } elif kind == "string" {
        gen[nid] = "\"" + rec["value"] + "\"";
    } elif kind == "module" {
        gen[nid] = joined(field_ids(nid, "body"), "\n");
    } elif kind == "param_var" {
        gen[nid] = first_gen(nid, "name") + ": " + first_gen(nid, "type_tag");
    } elif kind == "func_signature" {
        gen[nid] = "(" + comma_sep(field_ids(nid, "params")) + ") -> " + first_gen(nid, "return_type");
    } elif kind == "ability" {
        gen[nid] = "def " + first_gen(nid, "name") + first_gen(nid, "signature") + " { " + joined(field_ids(nid, "body"), " ") + " }";
    } elif kind == "return_stmt" {
        gen[nid] = "return " + first_gen(nid, "expr") + ";";
    } elif kind == "expr_stmt" {
        gen[nid] = first_gen(nid, "expr") + ";";
    } elif kind == "assignment" {
        gen[nid] = first_gen(nid, "target") + " = " + first_gen(nid, "value") + ";";
    } elif kind == "binary_expr" {
        gen[nid] = first_gen(nid, "left") + " " + first_gen(nid, "op") + " " + first_gen(nid, "right");
    } elif kind == "func_call" {
        gen[nid] = first_gen(nid, "target") + "(" + comma_sep(field_ids(nid, "params")) + ")";
    } elif kind == "atom_trailer" {
        gen[nid] = first_gen(nid, "target") + "." + first_gen(nid, "right");
    } elif kind == "if_stmt" {
        gen[nid] = "if " + first_gen(nid, "condition") + " { " + joined(field_ids(nid, "body"), " ") + " }";
    } elif kind == "list_val" {
        gen[nid] = "[" + comma_sep(field_ids(nid, "values")) + "]";
    } elif kind == "dict_val" {
        gen[nid] = "{" + comma_sep(field_ids(nid, "kv_pairs")) + "}";
    } elif kind == "k_v_pair" {
        gen[nid] = first_gen(nid, "key") + ": " + first_gen(nid, "value");
    } else {
        # Default: children's output joined in field order.
        all_ids: list[str] = [];
        for fname in rec["fields"].keys() {
            ids = rec["fields"][fname];
            i = 0;
            while i < len(ids) {
                all_ids.append(ids[i]);
                i = i + 1;
            }
        }
        gen[nid] = joined(all_ids, " ");
    }
}

def run_unparse(root_id: str) -> str {
    order: list[str] = [];
    stack: list[str] = [root_id];
    while len(stack) > 0 {
        cur = stack.pop();
        order.append(cur);
        for fname in nodes[cur]["fields"].keys() {
            ids = nodes[cur]["fields"][fname];
            i = 0;
            while i < len(ids) {
                stack.append(ids[i]);
                i = i + 1;
            }
        }
    }
    j = len(order) - 1;
    while j >= 0 {
        unparse_node(order[j]);
        j = j - 1;
    }
    return gen[root_id];
}

