"""Traversal-order fixture over four graph shapes (linear chain, diamond,
fan-out, cycle), rewritten without OSP: nodes are a flat value dict, edges an
adjacency map, and the visit-driven walk becomes an explicit DFS stack loop.

The unguarded tracer does NOT track visited nodes (visit-once is opt-in), so
the diamond double-visits its shared sink and a cycle would loop forever
unless guarded. chain/diamond/fanout use the unguarded trace; cycle uses the
guarded trace, which only pushes unseen nodes -- the user-managed visit-once
pattern. Neighbors are pushed in reverse so pop order matches the recursive
DFS order of the original kernel."""

glob node_vals: dict[str, int] = {};
glob adjacency: dict[str, list[str]] = {};

def reset_graph() -> None {
    node_vals.clear();
    adjacency.clear();
}

def add_node(nid: str, val: int) -> None {
    node_vals[nid] = val;
}

def connect(src: str, dst: str) -> None {
    if src not in adjacency {
        adjacency[src] = [];
    }
    adjacency[src].append(dst);
}

def push_reversed(stack: list[str], neighbors: list[str]) -> None {
    i = len(neighbors) - 1;
    while i >= 0 {
        stack.append(neighbors[i]);
        i = i - 1;
    }
}

def trace(start_id: str) -> list {
    seen: list[int] = [];
    stack: list[str] = [start_id];
    while len(stack) > 0 {
        cur = stack.pop();
        seen.append(node_vals[cur]);
        push_reversed(stack, adjacency.get(cur, []));
    }
    return seen;
}

def trace_guarded(start_id: str) -> list {
    seen: list[int] = [];
    stack: list[str] = [start_id];
    while len(stack) > 0 {
        cur = stack.pop();
        val = node_vals[cur];
        if val not in seen {
            seen.append(val);
            push_reversed(stack, adjacency.get(cur, []));
        }
    }
    return seen;
}

def chain_order() -> list {
    reset_graph();
    add_node("n1", 1); add_node("n2", 2); add_node("n3", 3); add_node("n4", 4);
    connect("n1", "n2"); connect("n2", "n3"); connect("n3", "n4");
    return trace("n1");
}

def diamond_order() -> list {
    # a -> b, a -> c, b -> d, c -> d : shared sink d is visited via both paths.
    reset_graph();
    add_node("a", 1); add_node("b", 2); add_node("c", 3); add_node("d", 4);
    connect("a", "b"); connect("a", "c"); connect("b", "d"); connect("c", "d");
    return trace("a");
}

def fanout_order() -> list {
    reset_graph();
    add_node("root", 1);
    add_node("c1", 2); add_node("c2", 3); add_node("c3", 4);
    connect("root", "c1"); connect("root", "c2"); connect("root", "c3");
    return trace("root");
}

def cycle_order() -> list {
    # 1 -> 2 -> 3 -> 1 : the guard stops the walk re-entering 1.
    reset_graph();
    add_node("n1", 1); add_node("n2", 2); add_node("n3", 3);
    connect("n1", "n2"); connect("n2", "n3"); connect("n3", "n1");
    return trace_guarded("n1");
}

def visit_order() -> dict[str, list] {
    return {
        "chain": chain_order(),
        "diamond": diamond_order(),
        "fanout": fanout_order(),
        "cycle": cycle_order()
    };
}

with entry {
