"""Helpers for generating target-specific JSX output, re-hosted on dict AST
records and plain functions (no processor classes over a linked node tree)."""

glob jsx_nodes: dict[str, dict] = {};
glob jsx_children: dict[str, list[str]] = {};

def add_jsx_node(nid: str, kind: str, fields: dict, parent: str = "") -> str {
    jsx_nodes[nid] = {"kind": kind, "fields": fields};
    jsx_children[nid] = [];
    if parent != "" {
        jsx_children[parent].append(nid);
    }
    return nid;
}

def es_element_name(nid: str) -> str {
    return str(jsx_nodes[nid]["fields"].get("name", "div"));
}

def es_text(nid: str) -> str {
    return '"' + str(jsx_nodes[nid]["fields"].get("value", "")) + '"';
}

def es_expression(nid: str) -> str {
    return "(" + str(jsx_nodes[nid]["fields"].get("code", "null")) + ")";
}

def es_normal_attribute(nid: str) -> str {
    f = jsx_nodes[nid]["fields"];
    return str(f.get("key", "k")) + ": " + str(f.get("value", "null"));
}

def es_spread_attribute(nid: str) -> str {
    return "..." + str(jsx_nodes[nid]["fields"].get("expr", "props"));
}

"""Process a JSX element dict into a __jacJsx(tag, props, children) call string."""
def es_element(nid: str) -> str {
    props: list[str] = [];
    kids: list[str] = [];
    for cid in jsx_children.get(nid, []) {
        kind = str(jsx_nodes[cid]["kind"]);
        if kind == "attr" {
            props.append(es_normal_attribute(cid));
        } elif kind == "spread" {
            props.append(es_spread_attribute(cid));
        } elif kind == "text" {
            kids.append(es_text(cid));
        } elif kind == "expr" {
            kids.append(es_expression(cid));
        } elif kind == "element" {
            kids.append(es_element(cid));
        }
    }
    tag = es_element_name(nid);
    return (
        '__jacJsx("' + tag + '", {' + ", ".join(props) + "}, ["
        + ", ".join(kids) + "])"
    );
}

"""Count nodes per kind with an explicit stack (Python-AST side bookkeeping)."""
def py_node_counts(start: str) -> dict[str, int] {
    counts: dict[str, int] = {};
    stack: list[str] = [start];
    while len(stack) > 0 {
        cur = stack.pop();
        kind = str(jsx_nodes[cur]["kind"]);
        counts[kind] = counts.get(kind, 0) + 1;
        for cid in jsx_children.get(cur, []) {
            stack.append(cid);
        }
    }
    return counts;
}

