glob modules: dict[str, dict] = {};

def register_module(path: str, stub_only: bool = False, annexable_by: str = "") -> None {
    modules[path] = {
        "stub_only": stub_only,
        "annexable_by": annexable_by,
        "impl_mod": [],
        "test_mod": [],
        "variant_mod": []
    };
}

def discover_annex_files(mod_path: str, suffix: str, known_files: list[str]) -> list[str] {
    base = mod_path[:-4] if mod_path.endswith(".jac") else mod_path;
    out: list[str] = [];
    for f in known_files {
        if f == base + suffix {
            out.append(f);
        }
    }
    return out;
}

def discover_variant_files(mod_path: str, known_files: list[str]) -> list[str] {
    base = mod_path[:-4] if mod_path.endswith(".jac") else mod_path;
    out: list[str] = [];
    for f in known_files {
        if f.startswith(base + ".") and f.endswith(".variant.jac") {
            out.append(f);
        }
    }
    return out;
}

def compile_stub(path: str) -> str {
    # stands in for jac_program.compile(file_path=path, no_cgen=True)
    return "compiled:" + path;
}

"""Load and attach annex records to the given module record."""
def load_annexes(mod_path: str, known_files: list[str]) -> None {
    rec = modules[mod_path];
    for path in discover_annex_files(mod_path, ".impl.jac", known_files) {
        mod = compile_stub(path);
        if mod {
            rec["impl_mod"].append(mod);
        }
    }
    for path in discover_annex_files(mod_path, ".test.jac", known_files) {
        mod = compile_stub(path);
        if mod {
            rec["test_mod"].append(mod);
        }
    }
    for path in discover_variant_files(mod_path, known_files) {
        mod = compile_stub(path);
        if mod {
            rec["variant_mod"].append(mod);
        }
    }
}

"""Transform: attach annexes unless the module is a stub, non-jac, or annexed itself."""
def transform(mod_path: str, known_files: list[str]) -> str {
    rec = modules[mod_path];
    if rec["stub_only"] or not mod_path.endswith(".jac") or rec["annexable_by"] {
        return mod_path;
    }
    load_annexes(mod_path, known_files);
    return mod_path;
}

