import marshal;

glob modules: dict[str, dict] = {};
glob module_children: dict[str, list[str]] = {};
glob errors: list[str] = [];

def register_module(name: str, source: str, parent: str = "") -> None {
    modules[name] = {"source": source, "bytecode": b""};
    module_children[name] = [];
    if parent != "" {
        module_children[parent].append(name);
    }
}

"""Compile a module record's source to serialized Python bytecode."""
def compile_module_to_bytecode(name: str) -> None {
    rec = modules[name];
    src = str(rec["source"]);
    if src == "" {
        errors.append("E5040 no source for " + name);
        return;
    }
    try {
        code = compile(src, name, "exec");
        rec["bytecode"] = marshal.dumps(code);
    } except (ValueError, SyntaxError, TypeError) as e {
        errors.append("E5043 " + name + ": " + str(e));
    }
}

"""Process the root module plus every sub-module, gathered with a queue."""
def process_modules(root_name: str) -> None {
    mods: list[str] = [];
    queue: list[str] = [root_name];
    while len(queue) > 0 {
        cur = queue.pop(0);
        mods.append(cur);
        for kid in module_children.get(cur, []) {
            queue.append(kid);
        }
    }
    for m in mods {
        compile_module_to_bytecode(m);
    }
}

def transform(root_name: str) -> str {
    process_modules(root_name);
    return root_name;
}

