glob ast_nodes: dict[str, dict] = {};
glob ast_children: dict[str, list[str]] = {};
glob diagnostics: list[str] = [];

def add_node(nid: str, kind: str, fields: dict, parent: str = "") -> str {
    ast_nodes[nid] = {"kind": kind, "fields": fields, "from_walker": False};
    ast_children[nid] = [];
    if parent != "" {
        ast_children[parent].append(nid);
    }
    return nid;
}

def get_all_sub_nodes(nid: str, kind: str) -> list[str] {
    out: list[str] = [];
    stack: list[str] = list(ast_children.get(nid, []));
    while len(stack) > 0 {
        cur = stack.pop();
        if str(ast_nodes[cur]["kind"]) == kind {
            out.append(cur);
        }
        for kid in ast_children.get(cur, []) {
            stack.append(kid);
        }
    }
    return out;
}

def emit(code: str, detail: str) -> None {
    diagnostics.append(code + " " + detail);
}

"""Mark traversal-flavored statements inside a walker archetype record."""
def inform_from_walker(nid: str) -> None {
    for kind in ["visit_stmt", "disengage_stmt", "edge_op_ref", "event_signature", "typed_ctx_block"] {
        for sub in get_all_sub_nodes(nid, kind) {
            ast_nodes[sub]["from_walker"] = True;
        }
    }
}

"""Check a single archetype record for attribute/method issues."""
def check_archetype(nid: str) -> None {
    rec = ast_nodes[nid];
    if str(rec["fields"].get("arch_type", "")) == "class" {
        return;
    }
    found_default_init = False;
    post_init_vars: list[str] = [];
    has_postinit_method = False;
    for item in ast_children.get(nid, []) {
        item_rec = ast_nodes[item];
        kind = str(item_rec["kind"]);
        if kind == "arch_has" {
            for var in ast_children.get(item, []) {
                vf = ast_nodes[var]["fields"];
                if vf.get("accessors", False) {
                    continue;  # property declarations aren't dataclass fields
                }
                if vf.get("has_value", False) or vf.get("defer", False) {
                    found_default_init = True;
                } elif found_default_init {
                    emit("E2004", str(vf.get("name", "?")) + " non-default after default");
                    break;
                }
                if vf.get("defer", False) {
                    post_init_vars.append(var);
                }
            }
        } elif kind == "ability" {
            af = item_rec["fields"];
            if af.get("is_abstract", False) {
                continue;
            }
            if str(af.get("name", "")) == "postinit" {
                has_postinit_method = True;
            }
            for dec in list(af.get("decorators", [])) {
                if str(dec) == "classmethod" {
                    emit("W2006", str(af.get("name", "?")));
                } elif str(dec) == "staticmethod" {
                    emit("W2007", str(af.get("name", "?")));
                }
            }
        }
    }
    if len(post_init_vars) != 0 and not has_postinit_method {
        emit("E2005", "deferred vars without postinit");
    }
}

def enter_archetype(nid: str) -> None {
    rec = ast_nodes[nid];
    if str(rec["fields"].get("arch_type", "")) == "walker" {
        inform_from_walker(nid);
    }
    check_archetype(nid);
}

