def compile_module_to_bytecode(name: str) -> None {
    src = module_source.get(name, "");
    if src == "" {
        gen_errors.append("E5040:" + name);
        return;
    }
    try {
        module_bytecode[name] = marshal.dumps(compile(src, name, "exec"));
    } except (ValueError, SyntaxError, TypeError) as e {
        gen_errors.append("E5043:" + name + ":" + str(e));
    }
}

def process_modules(root_name: str) -> None {
    queue: list[str] = [root_name];
    while len(queue) > 0 {
        cur = queue.pop(0);
        compile_module_to_bytecode(cur);
        for kid in module_kids.get(cur, []) {
            queue.append(kid);
        }
    }
}

def transform(root_name: str) -> str {
    process_modules(root_name);
    return root_name;
}

