def gen_diagnostics(from_path: str, errors: list[dict], warnings: list[dict]) -> list[dict] {
    out: list[dict] = [];
    for e in errors {
        if str(e["path"]) == from_path {
            out.append({"severity": 1, "message": e["msg"], "line": e["line"]});
        }
    }
    for w in warnings {
        if str(w["path"]) == from_path {
            out.append({"severity": 2, "message": w["msg"], "line": w["line"]});
        }
    }
    return out;
}

"""All tables (recursively) that belong to one file, via a queue."""
def sym_tab_list(root_tid: str, file_path: str) -> list[str] {
    out: list[str] = [];
    queue: list[str] = [root_tid];
    while len(queue) > 0 {
        cur = queue.pop(0);
        if str(tables[cur]["file_path"]) == file_path {
            out.append(cur);
        }
        for kid in table_kids.get(cur, []) {
            queue.append(kid);
        }
    }
    return out;
}

def position_within_node(nid: str, line: int, character: int) -> bool {
    n = nodes[nid];
    sl = int(str(n["start_line"]));
    el = int(str(n["end_line"]));
    if line < sl or line > el {
        return False;
    }
    if line == sl and character < int(str(n["start_col"])) {
        return False;
    }
    if line == el and character > int(str(n["end_col"])) {
        return False;
    }
    return True;
}

"""Deepest node containing (line, character): keep descending into whichever
kid still contains the position."""
def find_deepest_symbol_node_at_pos(root_nid: str, line: int, character: int) -> str {
    if not position_within_node(root_nid, line, character) {
        return "";
    }
    cur = root_nid;
    descending = True;
    while descending {
        descending = False;
        for kid in node_kids.get(cur, []) {
            if position_within_node(kid, line, character) {
                cur = kid;
                descending = True;
                break;
            }
        }
    }
    return cur;
}

def get_symbols_for_outline(root_tid: str) -> list[dict] {
    out: list[dict] = [];
    for kid in table_kids.get(root_tid, []) {
        out.append({"name": tables[kid]["scope_name"], "children": len(table_kids.get(kid, []))});
    }
