def put_node(anchor_id: str, node_type: str, owner_root: str) -> None {
    memory[anchor_id] = {"type": node_type, "root": owner_root};
    if owner_root not in topo_index {
        topo_index[owner_root] = {};
    }
    topo_index[owner_root][anchor_id] = [];
}

def put_edge(owner_root: str, src: str, tgt: str, edge_type: str) -> None {
    topo_index[owner_root][src].append({
        "edge_type": edge_type, "node_type": str(memory[tgt]["type"]), "to": tgt
    });
}

def trace(msg: str) -> None {
    if os.environ.get("JAC_QUERY_TRACE", "") != "" {
        print("[plan] " + msg);
    }
}

"""Resolve a chain on one root's index to a set of candidate ids.
Each hop narrows the frontier set through the adjacency lists."""
def plan_chain(root_id: str, origin_ids: list[str], chain: list[dict]) -> list[str] {
    index = topo_index.get(root_id);
    if index is None {
        return [];
    }
    frontier: list[str] = list(origin_ids);
    for hop in chain {
        nxt: list[str] = [];
        for src in frontier {
            for e in index.get(src, []) {
                et = str(hop.get("edge_type", ""));
                nt = str(hop.get("node_type", ""));
                if et != "" and str(e["edge_type"]) != et {
                    continue;
                }
                if nt != "" and str(e["node_type"]) != nt {
                    continue;
                }
                if str(e["to"]) not in nxt {
                    nxt.append(str(e["to"]));
                }
            }
        }
        frontier = nxt;
    }
    return frontier;
}

"""Ordered single-hop resolution with a slice applied afterwards."""
def plan_chain_ordered(
    root_id: str, origin_ids: list[str], edge_type: str, node_type: str,
    start: int, stop: int
) -> list[str] {
    hop = {"edge_type": edge_type, "node_type": node_type};
    ordered = plan_chain(root_id, origin_ids, [hop]);
    return ordered[start:stop];
}

def batch_get(ids: list[str]) -> list[dict] {
    out: list[dict] = [];
    for i in ids {
        rec = memory.get(i);
        if rec is not None {
            out.append({"id": i, "type": rec["type"]});
        }
    }
    return out;
}

def plan_needs(plan: dict) -> list[str] {
    needs: list[str] = [];
    for h in list(plan["chain"]) {
        if str(h.get("edge_type", "")) != "" or str(h.get("node_type", "")) != "" {
            if "type_pushdown" not in needs {
                needs.append("type_pushdown");
            }
        }
    }
    if len(plan.get("field_predicates", {})) > 0 {
        needs.append("field_pushdown");
    }
    return needs;
}

def covers(caps: list[str], needs: list[str]) -> bool {
    for n in needs {
        if n not in caps {
            return False;
        }
    }
    return True;
}

"""Top-level entry point: execute a plan dict against the dict memory."""
def execute_plan(plan: dict) -> list[dict] {
    needs = plan_needs(plan);
    if len(plan["chain"]) == 0 {
        trace("trivial plan refused");
        return [];
    }
    if covers(backend_caps, needs) {
        trace("strategy=pushdown " + str(needs));
        # backend would run natively; the floor doubles as the reference impl
    } else {
        trace("strategy=floor " + str(needs));
    }
    candidates = plan_chain(str(plan["root_id"]), list(plan["origin_ids"]), list(plan["chain"]));
    return batch_get(candidates);
}

with entry {
