"""QueryPlan IR rewritten as plain dict builders — the contract between the
planner and storage backends without archetype objects.

A hop dict is {edge_type, node_type, direction} (direction 1=IN, 2=OUT,
3=ANY, empty type strings mean "any"). Capability strings a backend can
declare: type_pushdown, field_pushdown, id_in, slice. Anything a plan needs
that the backend does not declare is applied above by the planner floor.
"""

glob CAP_TYPE: str = "type_pushdown";
glob CAP_FIELD: str = "field_pushdown";
glob CAP_ID_IN: str = "id_in";
glob CAP_SLICE: str = "slice";

def make_hop(edge_type: str = "", node_type: str = "", direction: int = 2) -> dict {
    return {"edge_type": edge_type, "node_type": node_type, "direction": direction};
}

"""Declarative plan record handed to backends or executed by the floor.
Only chain + root_id is the common case for [root -->]."""
def make_query_plan(
    root_id: str = "",
    chain: list[dict] = [],
    field_predicates: dict = {},
    id_in: list[str] = [],
    slc: dict = {},
    node_type_final: str = ""
) -> dict {
    return {
        "root_id": root_id,
        "chain": chain,
        "field_predicates": field_predicates,
        "id_in": id_in,
        "slc": slc,
        "node_type_final": node_type_final
    };
}

def plan_needs(plan: dict) -> list[str] {
    needs: list[str] = [];
    typed = str(plan["node_type_final"]) != "";
    for h in list(plan["chain"]) {
        if str(h["edge_type"]) != "" or str(h["node_type"]) != "" {
            typed = True;
        }
    }
    if typed {
        needs.append(CAP_TYPE);
    }
    if len(plan["field_predicates"]) > 0 {
        needs.append(CAP_FIELD);
    }
    if len(plan["id_in"]) > 0 {
        needs.append(CAP_ID_IN);
    }
    if len(plan["slc"]) > 0 {
        needs.append(CAP_SLICE);
    }
    return needs;
}

"""True when a backend declaring *caps* can take the plan as-is; otherwise
the planner strips the unmet needs and applies them above."""
def backend_covers(caps: list[str], plan: dict) -> bool {
    for n in plan_needs(plan) {
        if n not in caps {
            return False;
        }
    }
    return True;
}

"""Apply a declarative field predicate dict to one record (the $-operator
subset every backend understands)."""
def matches_predicates(fields: dict, predicates: dict) -> bool {
    for (name, cond) in predicates.items() {
        val = fields.get(name);
        if isinstance(cond, dict) {
            for (op, ref) in cond.items() {
                if op == "$eq" and not (val == ref) {
                    return False;
                } elif op == "$ne" and not (val != ref) {
                    return False;
                } elif op == "$lt" and not (val < ref) {
                    return False;
                } elif op == "$lte" and not (val <= ref) {
                    return False;
                } elif op == "$gt" and not (val > ref) {
                    return False;
                } elif op == "$gte" and not (val >= ref) {
                    return False;
                } elif op == "$in" and val not in list(ref) {
                    return False;
                } elif op == "$nin" and val in list(ref) {
                    return False;
                }
            }
        } elif val != cond {
            return False;
        }
    }
    return True;
}

with entry {
    plan = make_query_plan(
        root_id="root-1",
        chain=[make_hop("Follows", "User")],
        field_predicates={"age": {"$lt": 28}, "status": "active"}
    );
    print("needs: " + str(plan_needs(plan)));
    print("mongo-ish covers: " + str(backend_covers([CAP_TYPE, CAP_FIELD, CAP_ID_IN, CAP_SLICE], plan)));
    print("sqlite-ish covers: " + str(backend_covers([CAP_ID_IN], plan)));
    print("pred hit: " + str(matches_predicates({"age": 25, "status": "active"}, plan["field_predicates"])));
    print("pred miss: " + str(matches_predicates({"age": 30, "status": "active"}, plan["field_predicates"])));
}

