"""Scheduler rewritten as plain functions over a task list — no objects, no
background thread; a virtual clock loop drains due tasks deterministically."""

import heapq;

glob tasks: list[dict] = [];
glob run_log: list[str] = [];

def make_spec(date: str = "", interval: float = 0.0, cron: str = "") -> dict {
    return {"date": date, "interval": interval, "cron": cron};
}

def register(name: str, target: any, spec: dict) -> None {
    tasks.append({
        "name": name, "target": target, "spec": spec,
        "next_run": -1.0, "last_run": -1.0
    });
}

def compute_date(date_val: float, now: float) -> float {
    if date_val > now {
        return date_val;
    }
    return -1.0;
}

"""Next run time for a spec given the current (virtual) time; -1 = never."""
def compute_next_run(spec: dict, now: float) -> float {
    if str(spec["date"]) != "" {
        return compute_date(float(str(spec["date"])), now);
    }
    if float(str(spec["interval"])) > 0.0 {
        return now + float(str(spec["interval"]));
    }
    return -1.0;
}

def execute(task: dict, now: float) -> None {
    task["last_run"] = now;
    fn = task["target"];
    run_log.append(str(task["name"]) + "@" + str(now) + ":" + str(fn()));
}

def has_pending(now: float) -> bool {
    for t in tasks {
        if float(str(t["next_run"])) >= 0.0 {
            return True;
        }
    }
    return False;
}

"""Deterministic run loop over a min-heap of (when, index) pairs."""
def run_loop(until: float) -> None {
    heap: list = [];
    i = 0;
    while i < len(tasks) {
        nr = compute_next_run(tasks[i]["spec"], 0.0);
        tasks[i]["next_run"] = nr;
        if nr >= 0.0 {
            heapq.heappush(heap, (nr, i));
        }
        i = i + 1;
    }
    while len(heap) > 0 {
        (when, idx) = heapq.heappop(heap);
        if when > until {
            break;
        }
        task = tasks[idx];
        execute(task, when);
        spec = task["spec"];
        if float(str(spec["interval"])) > 0.0 {
            nxt = when + float(str(spec["interval"]));
            task["next_run"] = nxt;
            heapq.heappush(heap, (nxt, idx));
        } else {
            task["next_run"] = -1.0;
        }
    }
}

def tick_metrics() -> str {
    return "ok";
}

def one_shot() -> str {
    return "fired";
}

with entry {
    register("metrics", tick_metrics, make_spec(interval=2.0));
    register("report", one_shot, make_spec(date="5.0"));
    run_loop(6.0);
    for line in run_log {
        print(line);
    }
    print("pending after horizon: " + str(has_pending(6.0)));
}

"""Topology index maintenance hooks rewritten over dict adjacency maps.

Each root owns an index dict {src_id: [ {"to","edge_type"} ]}; the hooks keep
those dicts in sync with graph mutations (edge create/destroy, node
save/destroy). All are no-ops when the env flag is disabled. Cross-root
edges are mirrored into both endpoint owners' indexes so reverse queries
from the target side do not miss the edge."""

import os;

# root_id -> {src_id: [ {"to": id, "edge_type": name} ]}
glob root_indexes: dict[str, dict] = {};
# node_id -> owning root_id
glob node_owner: dict[str, str] = {};
# node_id -> type name (concrete first would carry the MRO chain)
glob node_type: dict[str, str] = {};

def is_enabled() -> bool {
    v = os.environ.get("JAC_TOPOLOGY_INDEX", "1").lower();
    return v in ["1", "true", "yes", "on"];
}

def get_root_of(node_id: str) -> str {
    return node_owner.get(node_id, "");
}

def type_name(node_id: str) -> str {
    return node_type.get(node_id, "object");
}

def index_edge_into(root_id: str, source: str, target: str, edge_type: str) -> None {
    if root_id not in root_indexes {
        root_indexes[root_id] = {};
    }
    idx = root_indexes[root_id];
    if source not in idx {
        idx[source] = [];
    }
    idx[source].append({"to": target, "edge_type": edge_type});
}

def unindex_edge_from(root_id: str, source: str, target: str, edge_type: str) -> None {
    idx = root_indexes.get(root_id, {});
    rows = idx.get(source, []);
    keep: list[dict] = [];
    removed = False;
    for r in rows {
        if not removed and str(r["to"]) == target and str(r["edge_type"]) == edge_type {
            removed = True;
            continue;
        }
        keep.append(r);
    }
    if source in idx {
        idx[source] = keep;
    }
}

def on_edge_created(source: str, target: str, edge_type: str) -> None {
    if not is_enabled() {
        return;
    }
    src_root = get_root_of(source);
    tgt_root = get_root_of(target);
    index_edge_into(src_root, source, target, edge_type);
    if tgt_root != "" and tgt_root != src_root {
        index_edge_into(tgt_root, source, target, edge_type);
    }
}

def on_edge_destroyed(source: str, target: str, edge_type: str) -> None {
    if not is_enabled() {
        return;
    }
    src_root = get_root_of(source);
    tgt_root = get_root_of(target);
    unindex_edge_from(src_root, source, target, edge_type);
    if tgt_root != "" and tgt_root != src_root {
        unindex_edge_from(tgt_root, source, target, edge_type);
    }
}

def on_node_saved(node_id: str, root_id: str, tname: str) -> None {
    if not is_enabled() {
        return;
    }
    node_owner[node_id] = root_id;
    node_type[node_id] = tname;
    if root_id not in root_indexes {
        root_indexes[root_id] = {};
    }
    if node_id not in root_indexes[root_id] {
        root_indexes[root_id][node_id] = [];
    }
}

def on_node_destroyed(node_id: str) -> None {
    if not is_enabled() {
        return;
    }
    root_id = get_root_of(node_id);
    idx = root_indexes.get(root_id, {});
    if node_id in idx {
        idx.pop(node_id);
    }
    for src in list(idx.keys()) {
        idx[src] = [r for r in idx[src] if str(r["to"]) != node_id];
    }
    if node_id in node_owner {
        node_owner.pop(node_id);
    }
}

with entry {
    on_node_saved("a", "r1", "User");
    on_node_saved("b", "r2", "User");
    on_edge_created("a", "b", "Follows");
    print("r1 sees: " + str(root_indexes["r1"]["a"]));
    print("r2 mirrored: " + str(root_indexes["r2"]["a"]));
    on_edge_destroyed("a", "b", "Follows");
    print("r1 after destroy: " + str(root_indexes["r1"]["a"]));
    on_node_destroyed("b");
    print("owners left: " + str(sorted(list(node_owner.keys()))));
}

