        bucket_add(tgt, "n:" + str(anc_id), src, "in");
    }
}

def remove_edge(source_id: str, target_id: str, edge_type_name: str) -> None {
    src = node_to_lid[source_id];
    tgt = node_to_lid[target_id];
    eid = type_to_id.get(edge_type_name, -1);
    keep: list[tuple] = [];
    dropped = False;
    for row in adj_list {
        if not dropped and row[0] == src and row[1] == eid and row[2] == tgt {
            dropped = True;
            continue;
        }
        keep.append(row);
    }
    adj_list.clear();
    adj_list.extend(keep);
    for col in list(buckets[src].keys()) {
        if tgt in buckets[src][col]["out"] {
            buckets[src][col]["out"].remove(tgt);
        }
    }
    for col in list(buckets[tgt].keys()) {
        if src in buckets[tgt][col]["in"] {
            buckets[tgt][col]["in"].remove(src);
        }
    }
}

"""Walk a hop chain entirely inside the index. With bail_on_foreign=True the
walk aborts the moment a non-final hop lands on a node owned by a different
root — that node's outgoing edges live in its own root's index."""
def resolve_chain(origin_ids: list[str], chain: list[dict], home_root: str = "", bail_on_foreign: bool = False) -> list[str] {
    frontier: list[int] = [];
    for oid in origin_ids {
        if oid in node_to_lid {
            frontier.append(node_to_lid[oid]);
        }
    }
    hop_i = 0;
    for hop in chain {
        is_final = hop_i == len(chain) - 1;
        nxt: list[int] = [];
        for lid in frontier {
            if bail_on_foreign and not is_final and home_root != "" {
                if str(node_table[lid]["owner"]) != home_root and hop_i > 0 {
                    return [];
                }
            }
            et = str(hop.get("edge_type", ""));
            nt = str(hop.get("node_type", ""));
            cols: list[str] = [];
            if et != "" {
                cols.append("e:" + str(type_to_id.get(et, -1)));
            } elif nt != "" {
                cols.append("n:" + str(type_to_id.get(nt, -1)));
            } else {
                cols = list(buckets[lid].keys());
            }
            for col in cols {
                bucket = buckets[lid].get(col);
                if bucket is None {
                    continue;
                }
                for t in bucket["out"] {
                    if nt != "" and et != "" {
                        anc = type_mro_ids[int(str(node_table[t]["type_id"]))];
                        if type_to_id.get(nt, -1) not in anc {
                            continue;
                        }
                    }
                    if t not in nxt {
                        nxt.append(t);
                    }
                }
            }
        }
        frontier = nxt;
        hop_i = hop_i + 1;
    }
    return [str(node_table[lid]["id"]) for lid in frontier];
}

"""Single-hop ordered resolution: walk the canonical adj_list in insertion
order and slice the resulting target ids."""
def resolve_chain_ordered(origin_ids: list[str], edge_type: str, node_type: str, start: int, stop: int) -> list[str] {
    origins: list[int] = [node_to_lid[o] for o in origin_ids if o in node_to_lid];
    eid = type_to_id.get(edge_type, -1);
    out: list[str] = [];
    for row in adj_list {
        if row[0] not in origins {
            continue;
        }
        if edge_type != "" and row[1] != eid {
            continue;
        }
        if node_type != "" {
            anc = type_mro_ids[int(str(node_table[row[2]]["type_id"]))];
            if type_to_id.get(node_type, -1) not in anc {
                continue;
            }
        }
        out.append(str(node_table[row[2]]["id"]));
    }
    return out[start:stop];
}

def encode() -> str {
    return json.dumps({
        "version": 2,
        "types": type_table,
        "nodes": node_table,
        "adj": [list(r) for r in adj_list]
    });
}

def index_len() -> int {
    return len(adj_list);
}

with entry {
