    if m is None { return -1.0; }
    return float(str(m.group(1)));
}


def parse_train(path: str) -> dict {
    series = {"train": [], "val": [], "lr": [], "tps": [],
              "itsec": [], "trained": [], "peak": []};
    p = Path(path);
    if not p.exists() {
        return series;
    }
    for line in p.read_text().split("\n") {
        m = re.search("Iter (\\d+)", line);
        if m is None { continue; }
        it = int(str(m.group(1)));
        tl = _num(line, "Train loss ([0-9.]+)");
        if tl >= 0.0 { series["train"].append([it, tl]); }
        vl = _num(line, "Val loss ([0-9.]+)");
        if vl >= 0.0 { series["val"].append([it, vl]); }
        lv = _num(line, "Learning Rate ([0-9.eE+-]+)");
        if lv >= 0.0 { series["lr"].append([it, lv]); }
        tv = _num(line, "Tokens/sec ([0-9.]+)");
        if tv >= 0.0 { series["tps"].append([it, tv]); }
        iv = _num(line, "It/sec ([0-9.]+)");
        if iv >= 0.0 { series["itsec"].append([it, iv]); }
        ttv = _num(line, "Trained Tokens ([0-9]+)");
        if ttv >= 0.0 { series["trained"].append([it, ttv]); }
        pv = _num(line, "Peak mem ([0-9.]+)");
        if pv >= 0.0 { series["peak"].append([it, pv]); }
    }
    return series;
}


def plot_one(points: list, title: str, ylabel: str, outpath: str) {
    if len(points) == 0 { return; }
    xs = [];
    ys = [];
    i = 0;
    while i < len(points) {
        xs.append(points[i][0]);
        ys.append(points[i][1]);
        i = i + 1;
    }
    pyplot.figure();  # jac:ignore[E1051]
    pyplot.plot(xs, ys, marker="o");  # jac:ignore[E1051,E1052]
    pyplot.title(title);  # jac:ignore[E1051]
    pyplot.xlabel("iteration");  # jac:ignore[E1051]
    pyplot.ylabel(ylabel);  # jac:ignore[E1051]
    pyplot.grid(True);  # jac:ignore[E1051]
    pyplot.savefig(outpath);  # jac:ignore[E1051]
    pyplot.close();  # jac:ignore[E1051]
    print("  wrote " + outpath);
}


