"""RL driver (guestbook): guestbook.explore_graph.walk_day.

Origin: this_is_jac/guestbook.jac. The explorer walks the guest graph
root -> Day -> Visitor, recording the visit order, the node views, the edges,
and a human log. The graph is a plain dict-of-lists adjacency map with a kind
tag per record; the traversal is a queue loop over that map. Nodes are
identified by stable keys (the day's date, the visitor's name) so stdout is
deterministic under plain `jac run`.
"""

glob node_db: dict[str, dict] = {};
glob adj: dict[str, list[str]] = {};
glob parent_of: dict[str, str] = {};

def add_node(nid: str, kind: str, label: str) -> None {
    node_db[nid] = {"kind": kind, "label": label};
}

def add_edge(src: str, dst: str) -> None {
    if src not in adj {
        adj[src] = [];
    }
    adj[src].append(dst);
    parent_of[dst] = src;
}

def explore_graph() -> dict {
    snap = {"nodes": [], "edges": [], "path": [], "log": []};
    rid = "root";
    snap["nodes"].append({"id": rid, "label": "root", "kind": "root"});
    snap["path"].append(rid);
    snap["log"].append("walker spawned at the shared root");

    queue: list[str] = [];
    for nb in adj.get(rid, []) {
        if node_db[nb]["kind"] == "day" {
            queue.append(nb);
        }
    }
    while len(queue) > 0 {
        cur = queue.pop(0);
        info = node_db[cur];
        if info["kind"] == "day" {
            did = info["label"];
            snap["nodes"].append({"id": did, "label": info["label"], "kind": "day"});
            snap["edges"].append([rid, did]);
            snap["path"].append(did);
            snap["log"].append("entered " + info["label"]);
            for nb in adj.get(cur, []) {
                if node_db[nb]["kind"] == "visitor" {
                    queue.append(nb);
                }
            }
        } elif info["kind"] == "visitor" {
            vid = info["label"];
            parent = parent_of.get(cur, "");
            did = node_db[parent]["label"] if parent in node_db else "root";
            snap["nodes"].append({"id": vid, "label": info["label"], "kind": "visitor"});
            snap["edges"].append([did, vid]);
            snap["path"].append(vid);
            snap["log"].append("visited " + info["label"]);
        }
    }
    snap["log"].append("traversal complete: " + str(len(snap["nodes"])) + " nodes");
    return snap;
}

