def created_key(t: dict) -> str {
    return t["created_at"];
}

def channel_to_view(
    channel: dict,
    cid: str,
    members: dict[str, list[str]],
    posts_by_channel: dict[str, list[dict]],
    profiles: list[dict],
    with_posts: bool
) -> dict {
    is_member = False;
    if len(profiles) > 0 {
        for u in members.get(cid, []) {
            if u == profiles[0]["username"] {
                is_member = True;
            }
        }
    }
    posts: list[dict] = [];
    if with_posts {
        for t in posts_by_channel.get(cid, []) {
            posts.append(tweet_to_view(t, profiles));
        }
        posts.sort(key=created_key, reverse=True);
    }
    return {
        "id": "",
        "name": channel["name"],
        "description": channel["description"],
        "creator_username": channel["creator_username"],
        "created_at": channel["created_at"],
        "member_count": len(members.get(cid, [])),
        "is_member": is_member,
        "posts": posts
    };
